import { ref } from 'vue';
import {
    Group, Mesh, BoxGeometry, SphereGeometry, CylinderGeometry,
    MeshStandardMaterial, CanvasTexture, SpriteMaterial, Sprite,
} from 'three';
import { AvatarAnimator, AVATAR_STATES } from '@/Support/Office/animations/avatarStateMachine.js';
import { findPath, getZoneEntryPoint } from '@/Support/Office/animations/pathfinding.js';
import { IdleBehaviorScheduler } from '@/Support/Office/animations/idleBehavior.js';

const AGENT_COLORS = [
    0x3b82f6, 0x10b981, 0xf59e0b, 0x8b5cf6, 0xec4899,
    0x06b6d4, 0xf97316, 0x84cc16, 0xe11d48,
];

function createImprovedAvatar(agent, colorIndex) {
    const group = new Group();
    const color = AGENT_COLORS[colorIndex % AGENT_COLORS.length];
    const bodyMat = new MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.1 });
    const skinMat = new MeshStandardMaterial({ color: 0xddb892, roughness: 0.8 });
    const darkMat = new MeshStandardMaterial({ color: 0x333333 });

    const body = new Mesh(new BoxGeometry(0.35, 0.5, 0.2), bodyMat);
    body.position.y = 0.55;
    body.castShadow = true;
    group.add(body);

    const head = new Mesh(new SphereGeometry(0.14, 12, 8), skinMat);
    head.position.y = 0.95;
    head.castShadow = true;
    group.add(head);

    const leftArm = new Mesh(new BoxGeometry(0.08, 0.4, 0.08), bodyMat);
    leftArm.position.set(-0.24, 0.55, 0);
    leftArm.castShadow = true;
    group.add(leftArm);

    const rightArm = new Mesh(new BoxGeometry(0.08, 0.4, 0.08), bodyMat);
    rightArm.position.set(0.24, 0.55, 0);
    rightArm.castShadow = true;
    group.add(rightArm);

    const leftLeg = new Mesh(new BoxGeometry(0.1, 0.3, 0.1), darkMat);
    leftLeg.position.set(-0.1, 0.15, 0);
    leftLeg.castShadow = true;
    group.add(leftLeg);

    const rightLeg = new Mesh(new BoxGeometry(0.1, 0.3, 0.1), darkMat);
    rightLeg.position.set(0.1, 0.15, 0);
    rightLeg.castShadow = true;
    group.add(rightLeg);

    group.userData = {
        agentId: agent.id,
        agentName: agent.name,
        interactive: true,
        type: 'agent',
    };

    return group;
}

function createNameplate(name) {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = 'rgba(15,20,40,0.85)';
    const r = 10;
    ctx.beginPath();
    ctx.roundRect(4, 4, 248, 56, r);
    ctx.fill();
    ctx.strokeStyle = 'rgba(100,140,255,0.4)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(4, 4, 248, 56, r);
    ctx.stroke();
    ctx.font = 'bold 22px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#e0e8ff';
    ctx.fillText(name, 128, 32);

    const texture = new CanvasTexture(canvas);
    const spriteMat = new SpriteMaterial({ map: texture, depthTest: false });
    const sprite = new Sprite(spriteMat);
    sprite.scale.set(1.2, 0.3, 1);
    sprite.position.y = 1.3;
    return sprite;
}

export function useAgentAvatars(scene) {
    const avatars = ref(new Map());
    const animators = new Map();
    const idleScheduler = new IdleBehaviorScheduler();

    function addAgent(agent, position, colorIndex) {
        const group = createImprovedAvatar(agent, colorIndex);
        group.position.set(position.x, 0, position.z);

        const nameplate = createNameplate(agent.name || `Agent ${agent.id}`);
        group.add(nameplate);

        scene.add(group);
        avatars.value.set(agent.id, group);

        const animator = new AvatarAnimator(group);
        animators.set(agent.id, animator);

        idleScheduler.register(agent.id, position);

        return { group, animator };
    }

    function removeAgent(agentId) {
        const group = avatars.value.get(agentId);
        if (group) {
            scene.remove(group);
            avatars.value.delete(agentId);
            animators.delete(agentId);
            idleScheduler.unregister(agentId);
        }
    }

    function setAgentState(agentId, state) {
        const animator = animators.get(agentId);
        if (animator) animator.setState(state);
    }

    function moveAgentToZone(agentId, zoneId) {
        const animator = animators.get(agentId);
        const group = avatars.value.get(agentId);
        if (!animator || !group) return;

        const target = getZoneEntryPoint(zoneId);
        const from = { x: group.position.x, z: group.position.z };
        const path = findPath(from, target);
        animator.walkAlongPath(path);
    }

    function moveAgentToPosition(agentId, targetPos) {
        const animator = animators.get(agentId);
        const group = avatars.value.get(agentId);
        if (!animator || !group) return;

        const from = { x: group.position.x, z: group.position.z };
        const path = findPath(from, targetPos);
        animator.walkAlongPath(path);
    }

    function updateAll(delta) {
        animators.forEach((animator) => animator.update(delta));
        idleScheduler.tick(delta, api);
    }

    function getAvatarGroup(agentId) {
        return avatars.value.get(agentId);
    }

    function setAgentBusy(agentId, busy) {
        idleScheduler.setBusy(agentId, busy);
        if (busy) {
            idleScheduler.forceReturn(agentId, api);
        }
    }

    function _getAnimator(agentId) {
        return animators.get(agentId);
    }

    function dispose() {
        avatars.value.forEach((group) => scene.remove(group));
        avatars.value.clear();
        animators.clear();
        idleScheduler.dispose();
    }

    const api = {
        avatars,
        addAgent,
        removeAgent,
        setAgentState,
        setAgentBusy,
        moveAgentToZone,
        moveAgentToPosition,
        updateAll,
        getAvatarGroup,
        _getAnimator,
        dispose,
        AVATAR_STATES,
    };

    return api;
}

import { ref, onUnmounted } from 'vue';
import axios from 'axios';

const POLL_INTERVAL = 5000;

function inferActivityFromName(name) {
    if (!name) return 'working';
    const lower = name.toLowerCase();
    if (lower.includes('review')) return 'reviewing';
    if (lower.includes('analysis') || lower.includes('analy')) return 'analyzing';
    if (lower.includes('synthesis') || lower.includes('report')) return 'compiling_report';
    if (lower.includes('test')) return 'testing';
    if (lower.includes('refactor')) return 'refactoring';
    if (lower.includes('fix') || lower.includes('debug')) return 'debugging';
    if (lower.includes('plan') || lower.includes('design')) return 'planning';
    if (lower.includes('write') || lower.includes('implement') || lower.includes('build')) return 'writing_code';
    return 'working';
}

export function useOfficeRealtime() {
    const officeState = ref(null);
    const connected = ref(false);
    const lastUpdate = ref(null);
    const agentOutputQueue = ref([]);

    let pollTimer = null;
    let echoChannel = null;

    async function fetchState() {
        try {
            const { data } = await axios.get('/agent/api/v1/office/state');
            officeState.value = data?.data ?? null;
            lastUpdate.value = Date.now();
            return officeState.value;
        } catch {
            return null;
        }
    }

    function subscribeEcho(userId) {
        if (!window.Echo) return;
        try {
            echoChannel = window.Echo.private(`office.${userId}`);
            echoChannel.listen('.activity.changed', (event) => {
                handleRealtimeEvent(event);
            });
            connected.value = true;
        } catch {
            connected.value = false;
        }
    }

    function handleRealtimeEvent(event) {
        if (!officeState.value) return;

        const { event_type, payload } = event;

        switch (event_type) {
            case 'run.status_changed': {
                const agent = officeState.value.agents?.find((a) => a.id === payload.agent_id);
                if (agent) {
                    agent.status = payload.status;
                    agent.current_activity = payload.activity ?? 'idle';
                    agent.current_run = payload.run ?? null;
                }
                break;
            }
            case 'session.updated': {
                const agent = officeState.value.agents?.find((a) => a.id === payload.agent_id);
                if (agent) {
                    agent.current_session = payload.session ?? null;
                }
                break;
            }
            case 'system.health': {
                Object.assign(officeState.value.system, payload);
                break;
            }
            case 'delegation.updated': {
                Object.assign(officeState.value.delegation, payload);
                break;
            }
            case 'delegation.graph_created': {
                if (officeState.value.delegation) {
                    officeState.value.delegation.active_graphs = (officeState.value.delegation.active_graphs ?? 0) + 1;
                }
                break;
            }
            case 'ritual.started': {
                officeState.value.agents?.forEach((agent) => {
                    if (agent.role !== 'coordinator') return;
                    agent.zone = 'conference';
                    agent.current_activity = 'reading';
                    agent.status = 'running';
                });
                break;
            }
            case 'ritual.phase_started': {
                const agent = officeState.value.agents?.find((a) => a.id === payload.agent_id);
                if (agent) {
                    agent.status = 'running';
                    agent.current_activity = inferActivityFromName(payload.task_name ?? payload.phase_name);
                    agent.zone = 'workstation';
                }
                break;
            }
            case 'ritual.phase_completed': {
                const agent = officeState.value.agents?.find((a) => a.id === payload.agent_id);
                if (agent) {
                    agent.status = 'idle';
                    agent.current_activity = 'idle';
                }
                break;
            }
            case 'council.deliberation_started': {
                officeState.value.agents?.forEach((agent) => {
                    if (payload.member_ids?.includes(agent.id)) {
                        agent.zone = 'conference';
                        agent.current_activity = 'chatting';
                        agent.status = 'running';
                    }
                });
                break;
            }
            case 'council.deliberation_ended': {
                officeState.value.agents?.forEach((agent) => {
                    if (payload.member_ids?.includes(agent.id)) {
                        agent.zone = 'workstation';
                        agent.current_activity = 'idle';
                        agent.status = 'idle';
                    }
                });
                break;
            }
            case 'ritual.failed': {
                officeState.value.agents?.forEach((agent) => {
                    if (agent.role === 'coordinator') {
                        agent.zone = 'escalation';
                        agent.current_activity = 'waiting';
                    }
                });
                break;
            }
            case 'messenger.updated': {
                if (payload.channels) officeState.value.messenger.channels = payload.channels;
                break;
            }
            case 'memory.formed': {
                if (officeState.value.memory) {
                    officeState.value.memory.total_entries = payload.total_entries ?? officeState.value.memory.total_entries;
                    officeState.value.memory.recent_formations = (officeState.value.memory.recent_formations ?? 0) + 1;
                }
                break;
            }
            case 'agent.output': {
                agentOutputQueue.value.push({
                    run_id: payload.run_id,
                    text: payload.text,
                    at: Date.now(),
                });
                if (agentOutputQueue.value.length > 20) {
                    agentOutputQueue.value = agentOutputQueue.value.slice(-20);
                }
                break;
            }
            case 'delegation.task_completed': {
                const agent = officeState.value.agents?.find(
                    (a) => a.current_delegation_task?.id === payload.task_id,
                );
                if (agent) {
                    agent.status = 'idle';
                    agent.current_activity = 'idle';
                    agent.current_delegation_task = null;
                }
                agentOutputQueue.value.push({
                    event_type: 'task_completed',
                    task_name: payload.task_name,
                    next_tasks: payload.next_tasks ?? [],
                    delegatee_profile_id: payload.delegatee_profile_id,
                    at: Date.now(),
                });
                break;
            }
            case 'agent.escalation': {
                agentOutputQueue.value.push({
                    event_type: 'escalation',
                    run_id: payload.run_id,
                    job_name: payload.job_name,
                    reason: payload.reason,
                    summary: payload.summary,
                    at: Date.now(),
                });
                break;
            }
        }

        lastUpdate.value = Date.now();
    }

    function startPolling() {
        if (pollTimer) return;
        fetchState();
        pollTimer = setInterval(fetchState, POLL_INTERVAL);
    }

    function stopPolling() {
        if (pollTimer) {
            clearInterval(pollTimer);
            pollTimer = null;
        }
    }

    function start(userId) {
        startPolling();
        if (userId) subscribeEcho(userId);
    }

    function stop() {
        stopPolling();
        if (echoChannel) {
            try { echoChannel.stopListening('.activity.changed'); } catch {}
            echoChannel = null;
        }
        connected.value = false;
    }

    onUnmounted(() => stop());

    return {
        officeState,
        connected,
        lastUpdate,
        agentOutputQueue,
        fetchState,
        start,
        stop,
    };
}

import { ref, watch } from 'vue';
import { MeshStandardMaterial, CanvasTexture, Color } from 'three';

const STATUS_COLORS = {
    running: new Color(0x10b981),
    idle: new Color(0x3b82f6),
    waiting: new Color(0xf59e0b),
    failed: new Color(0xef4444),
    succeeded: new Color(0x22c55e),
    queued: new Color(0x6366f1),
    starting: new Color(0x06b6d4),
};

function findMeshByType(scene, type) {
    const results = [];
    scene.traverse((obj) => {
        if (obj.userData?.type === type) results.push(obj);
    });
    return results;
}

function findMeshByZoneId(scene, zoneId) {
    const results = [];
    scene.traverse((obj) => {
        if (obj.userData?.zoneId === zoneId) results.push(obj);
    });
    return results;
}

function updateDeskLamp(workstation, status) {
    const color = STATUS_COLORS[status] || STATUS_COLORS.idle;
    workstation.traverse((child) => {
        if (child.isMesh && child.material?.emissive) {
            const geom = child.geometry?.parameters;
            if (geom && geom.width < 0.5 && geom.height < 0.4 && geom.depth < 0.02) {
                child.material.emissive.copy(color);
                child.material.emissiveIntensity = status === 'running' ? 0.5 : 0.2;
            }
        }
    });
}

const monitorCanvases = new Map();
const MONITOR_CANVAS_W = 128;
const MONITOR_CANVAS_H = 96;

function getOrCreateMonitorCanvas(workstationIndex) {
    if (monitorCanvases.has(workstationIndex)) return monitorCanvases.get(workstationIndex);
    const canvas = document.createElement('canvas');
    canvas.width = MONITOR_CANVAS_W;
    canvas.height = MONITOR_CANVAS_H;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, MONITOR_CANVAS_W, MONITOR_CANVAS_H);
    const texture = new CanvasTexture(canvas);
    monitorCanvases.set(workstationIndex, { canvas, ctx, texture });
    return { canvas, ctx, texture };
}

function animateCodeCanvas(ctx, canvas) {
    const imgData = ctx.getImageData(0, 1, canvas.width, canvas.height - 1);
    ctx.putImageData(imgData, 0, 0);

    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(0, canvas.height - 1, canvas.width, 1);

    if (Math.random() < 0.7) {
        const indent = Math.floor(Math.random() * 5) * 8;
        const lineLen = 10 + Math.floor(Math.random() * 60);
        const hue = Math.random() < 0.3 ? '#66dd88' : Math.random() < 0.5 ? '#88aaff' : '#aaddaa';
        ctx.fillStyle = hue;
        ctx.fillRect(indent, canvas.height - 1, lineLen, 1);

        if (Math.random() < 0.3) {
            ctx.fillStyle = '#dd8844';
            ctx.fillRect(indent + lineLen + 4, canvas.height - 1, 15 + Math.floor(Math.random() * 20), 1);
        }
    }
}

function updateMonitorScreen(workstation, activity, time) {
    const wsIndex = workstation.userData?.workstationIndex;

    workstation.traverse((child) => {
        if (child.isMesh && child.material?.emissive) {
            const geom = child.geometry?.parameters;
            if (geom && geom.depth < 0.01 && geom.width > 0.3) {
                const screenActiveActivities = [
                    'writing_code', 'analyzing', 'reviewing', 'compiling_report',
                    'testing', 'refactoring', 'debugging', 'planning',
                    'working', 'executing_job',
                ];
                if (screenActiveActivities.includes(activity) && wsIndex !== undefined) {
                    const mc = getOrCreateMonitorCanvas(wsIndex);
                    animateCodeCanvas(mc.ctx, mc.canvas);
                    mc.texture.needsUpdate = true;
                    child.material.map = mc.texture;
                    const screenColor = activity === 'reviewing' || activity === 'analyzing'
                        ? new Color(0x0088ff)
                        : activity === 'compiling_report'
                            ? new Color(0xff8800)
                            : activity === 'debugging'
                                ? new Color(0xff4444)
                                : new Color(0x00ff44);
                    child.material.emissive.copy(screenColor);
                    child.material.emissiveIntensity = 0.3;
                } else {
                    child.material.map = null;
                    const color = activity === 'waiting'
                        ? new Color(0xffaa00)
                        : new Color(0x003322);
                    child.material.emissive.copy(color);
                    child.material.emissiveIntensity = activity === 'idle' ? 0.05 : 0.4;
                }
                child.material.needsUpdate = true;
            }
        }
    });
}

function updateServerRackLeds(scene, systemState, time) {
    const racks = findMeshByType(scene, 'serverRack');
    racks.forEach((rack) => {
        rack.traverse((child) => {
            if (child.isMesh && child.material?.emissive) {
                const isLed = child.geometry?.type === 'SphereGeometry';
                if (isLed) {
                    if (systemState.scheduler_healthy) {
                        child.material.emissiveIntensity = 0.5 + Math.sin(time * 4 + child.position.y * 10) * 0.3;
                    } else {
                        child.material.emissive.setHex(0xff0000);
                        child.material.emissiveIntensity = Math.sin(time * 8) > 0 ? 0.8 : 0.1;
                    }
                }
            }
        });
    });
}

function updateTrafficLight(scene, systemState) {
    const lights = findMeshByType(scene, 'trafficLight');
    lights.forEach((tl) => {
        let ledIndex = 0;
        tl.traverse((child) => {
            if (child.isMesh && child.geometry?.type === 'SphereGeometry') {
                const isRed = ledIndex === 0;
                const isAmber = ledIndex === 1;
                const isGreen = ledIndex === 2;

                if (systemState.rate_limited) {
                    child.material.emissiveIntensity = isRed ? 0.8 : 0.05;
                } else if (systemState.active_runs > 3) {
                    child.material.emissiveIntensity = isAmber ? 0.8 : 0.05;
                } else {
                    child.material.emissiveIntensity = isGreen ? 0.8 : 0.05;
                }
                ledIndex++;
            }
        });
    });
}

function updateScreenWall(scene, systemState, time) {
    const walls = findMeshByType(scene, 'screenWall');
    walls.forEach((wall) => {
        wall.traverse((child) => {
            if (child.isMesh && child.material?.emissive) {
                const geom = child.geometry?.parameters;
                if (geom && geom.depth < 0.01) {
                    const intensity = systemState.active_runs > 0
                        ? 0.3 + Math.sin(time * 2 + child.position.x) * 0.1
                        : 0.1;
                    child.material.emissiveIntensity = intensity;
                    if (systemState.active_runs > 0) {
                        child.material.emissive.setHex(0x003355);
                    } else {
                        child.material.emissive.setHex(0x001122);
                    }
                }
            }
        });
    });
}

function updateBarrier(scene, systemState) {
    const barriers = findMeshByType(scene, 'barrier');
    barriers.forEach((barrier) => {
        barrier.traverse((child) => {
            if (child.isMesh && child.geometry?.type === 'SphereGeometry') {
                const mode = systemState.runtime_mode;
                const color = mode === 'full'
                    ? 0x00ff00
                    : mode === 'standard'
                        ? 0xffaa00
                        : 0xff0000;
                child.material.emissive.setHex(color);
                child.material.emissiveIntensity = 0.6;
            }
        });
    });
}

function updateBookshelfFill(scene, memoryState) {
    const shelves = findMeshByType(scene, 'bookshelf');
    shelves.forEach((shelf) => {
        if (memoryState.recent_formations > 0) {
            shelf.traverse((child) => {
                if (child.isMesh && child.material?.emissive) {
                    child.material.emissiveIntensity = 0.15;
                }
            });
        }
    });
}

function updateAlarmBell(scene, systemState, time) {
    const alarms = findMeshByType(scene, 'alarmBell');
    const hasEscalation = systemState.rate_limited || systemState.active_runs > 5;
    alarms.forEach((alarm) => {
        alarm.traverse((child) => {
            if (child.isMesh && child.material?.emissive) {
                if (hasEscalation) {
                    child.material.emissiveIntensity = 0.4 + Math.sin(time * 6) * 0.4;
                } else {
                    child.material.emissiveIntensity = 0.1;
                }
            }
        });
    });
}

function updateMailStations(scene, messengerState) {
    const stations = findMeshByType(scene, 'mailStation');
    const channels = messengerState?.channels ?? [];
    stations.forEach((station, i) => {
        const channel = channels[i];
        station.traverse((child) => {
            if (child.isMesh && child.material?.emissive) {
                if (channel?.status === 'connected') {
                    child.material.emissiveIntensity = 0.3;
                } else {
                    child.material.emissiveIntensity = 0.02;
                }
            }
        });
    });
}

function updateConferenceRoom(scene, delegationState) {
    const whiteboards = findMeshByType(scene, 'whiteboard');
    const active = delegationState.active_graphs > 0;
    whiteboards.forEach((wb) => {
        wb.traverse((child) => {
            if (child.isMesh) {
                const geom = child.geometry?.parameters;
                if (geom && geom.depth < 0.02 && child.material?.color) {
                    if (active) {
                        child.material.emissive = child.material.emissive || new Color();
                        child.material.emissive.setHex(0xffffff);
                        child.material.emissiveIntensity = 0.15;
                    } else {
                        if (child.material.emissive) {
                            child.material.emissiveIntensity = 0;
                        }
                    }
                }
            }
        });
    });
}

function updateToolBenches(scene, agentStates) {
    const benches = findMeshByType(scene, 'toolBench');
    const activeTools = new Set();
    (agentStates ?? []).forEach((a) => {
        (a.tools_active ?? []).forEach((t) => activeTools.add(t));
    });

    benches.forEach((bench) => {
        const toolType = bench.userData?.toolType;
        const isActive = activeTools.has(toolType);
        bench.traverse((child) => {
            if (child.isMesh && child.material?.emissive) {
                child.material.emissiveIntensity = isActive ? 0.5 : 0.1;
            }
        });
    });
}

export function useOfficeZones(scene, officeState, avatarApi) {
    let lastAnimTime = 0;

    function updateZones(time) {
        lastAnimTime = time;
        const state = officeState.value;
        if (!state || !scene) return;

        const agentStates = state.agents ?? [];
        const system = state.system ?? {};
        const delegation = state.delegation ?? {};
        const messenger = state.messenger ?? {};
        const memory = state.memory ?? {};

        const workstations = findMeshByType(scene, 'workstation');
        workstations.forEach((ws) => {
            const wsIdx = ws.userData?.workstationIndex;
            if (wsIdx === undefined) return;
            const agent = agentStates[wsIdx];
            if (agent) {
                updateDeskLamp(ws, agent.status);
                updateMonitorScreen(ws, agent.current_activity, time);
            } else {
                updateDeskLamp(ws, 'idle');
                updateMonitorScreen(ws, 'idle', time);
            }
        });

        // Server Room
        updateServerRackLeds(scene, system, time);
        updateTrafficLight(scene, system);

        // War Room
        updateScreenWall(scene, system, time);

        // Security Desk
        updateBarrier(scene, system);

        // Archives
        updateBookshelfFill(scene, memory);

        // Escalation
        updateAlarmBell(scene, system, time);

        // Mailroom
        updateMailStations(scene, messenger);

        // Conference
        updateConferenceRoom(scene, delegation);

        // Tool Workshop
        updateToolBenches(scene, agentStates);

        if (avatarApi) {
            agentStates.forEach((agent) => {
                const isBusy = agent.current_activity !== 'idle';
                const inNonDeskZone = agent.zone && agent.zone !== 'workstation' && agent.zone !== 'workstations';

                if (isBusy && !inNonDeskZone) {
                    avatarApi.setAgentBusy(agent.id, true);
                } else if (!isBusy) {
                    avatarApi.setAgentBusy(agent.id, false);
                }

                if (isBusy) {
                    const stateMap = {
                        writing_code: 'typing',
                        analyzing: 'reading',
                        reviewing: 'reading',
                        compiling_report: 'typing',
                        testing: 'typing',
                        refactoring: 'typing',
                        debugging: 'reading',
                        planning: 'reading',
                        working: 'typing',
                        executing_job: 'typing',
                        reading: 'reading',
                        waiting: 'waiting',
                        finishing: 'typing',
                        chatting: 'chatting',
                    };
                    const avatarState = stateMap[agent.current_activity] || 'typing';
                    avatarApi.setAgentState(agent.id, avatarState);
                }
            });
        }
    }

    return {
        updateZones,
    };
}

export const AVATAR_STATES = {
    IDLE: 'idle',
    WALKING: 'walking',
    TYPING: 'typing',
    READING: 'reading',
    WAITING: 'waiting',
    CHATTING: 'chatting',
};

export class AvatarAnimator {
    constructor(avatarGroup) {
        this.group = avatarGroup;
        this.state = AVATAR_STATES.IDLE;
        this.stateTime = 0;
        this.targetPosition = null;
        this.walkSpeed = 2.5;
        this.walkPath = [];
        this.pathIndex = 0;
        this.onArrive = null;
        this._headRef = null;
        this._bodyRef = null;
        this._armsRef = { left: null, right: null };
        this._legsRef = { left: null, right: null };
        this._baseY = {};
        this._identifyParts();
    }

    _identifyParts() {
        const sorted = [...this.group.children]
            .filter((c) => c.isMesh)
            .sort((a, b) => b.position.y - a.position.y);

        for (const child of sorted) {
            const h = child.geometry?.parameters?.height;
            if (!this._headRef && child.position.y > 0.7) {
                this._headRef = child;
                this._baseY.head = child.position.y;
            } else if (!this._bodyRef && h && h > 0.3 && h < 0.7 && child.position.y > 0.3) {
                this._bodyRef = child;
                this._baseY.body = child.position.y;
            }
        }

        const remaining = sorted.filter((c) => c !== this._bodyRef && c !== this._headRef);
        const arms = remaining.filter((c) => c.position.y > 0.4);
        const legs = remaining.filter((c) => c.position.y <= 0.4);

        if (arms[0]) { this._armsRef.left = arms[0]; this._baseY.leftArm = arms[0].position.y; }
        if (arms[1]) { this._armsRef.right = arms[1]; this._baseY.rightArm = arms[1].position.y; }
        if (legs[0]) { this._legsRef.left = legs[0]; this._baseY.leftLeg = legs[0].position.y; }
        if (legs[1]) { this._legsRef.right = legs[1]; this._baseY.rightLeg = legs[1].position.y; }
    }

    setState(newState) {
        if (this.state === newState) return;
        this._resetPose();
        this.state = newState;
        this.stateTime = 0;
    }

    walkTo(targetPos) {
        this.targetPosition = { x: targetPos.x, z: targetPos.z };
        this.setState(AVATAR_STATES.WALKING);
    }

    walkAlongPath(path) {
        if (!path || path.length === 0) return;

        const cur = this.group.position;
        const filtered = path.filter((wp) => {
            const dx = wp.x - cur.x;
            const dz = wp.z - cur.z;
            return Math.sqrt(dx * dx + dz * dz) > 0.1;
        });
        if (filtered.length === 0) {
            this._resetPose();
            this.setState(AVATAR_STATES.IDLE);
            if (this.onArrive) this.onArrive();
            return;
        }

        this.walkPath = filtered;
        this.pathIndex = 0;
        this.targetPosition = { x: filtered[0].x, z: filtered[0].z };
        this.setState(AVATAR_STATES.WALKING);
    }

    get isWalking() {
        return this.state === AVATAR_STATES.WALKING;
    }

    update(delta) {
        if (Number.isNaN(this.group.position.x) || Number.isNaN(this.group.position.z)) {
            this.group.position.x = 0;
            this.group.position.z = 0;
            this.targetPosition = null;
            this.walkPath = [];
            this._resetPose();
            this.state = AVATAR_STATES.IDLE;
            return;
        }

        this.stateTime += delta;

        switch (this.state) {
            case AVATAR_STATES.IDLE:
                this._animateIdle(delta);
                break;
            case AVATAR_STATES.WALKING:
                this._animateWalking(delta);
                break;
            case AVATAR_STATES.TYPING:
                this._animateTyping(delta);
                break;
            case AVATAR_STATES.READING:
                this._animateReading(delta);
                break;
            case AVATAR_STATES.WAITING:
                this._animateWaiting(delta);
                break;
            case AVATAR_STATES.CHATTING:
                this._animateChatting(delta);
                break;
        }
    }

    _animateIdle(delta) {
        const bob = Math.sin(this.stateTime * 1.5) * 0.01;
        if (this._bodyRef) this._bodyRef.position.y = this._baseY.body + bob;
        if (this._headRef) this._headRef.position.y = this._baseY.head + bob * 1.2;
    }

    _animateWalking(delta) {
        if (!this.targetPosition) {
            this._resetPose();
            this.setState(AVATAR_STATES.IDLE);
            return;
        }

        const dx = this.targetPosition.x - this.group.position.x;
        const dz = this.targetPosition.z - this.group.position.z;
        const dist = Math.sqrt(dx * dx + dz * dz);

        if (dist < 0.15 || dist === 0) {
            this.group.position.x = this.targetPosition.x;
            this.group.position.z = this.targetPosition.z;

            if (this.walkPath.length > 0 && this.pathIndex < this.walkPath.length - 1) {
                this.pathIndex++;
                this.targetPosition = { x: this.walkPath[this.pathIndex].x, z: this.walkPath[this.pathIndex].z };
                return;
            }

            this.targetPosition = null;
            this.walkPath = [];
            this._resetPose();
            this.setState(AVATAR_STATES.IDLE);
            if (this.onArrive) this.onArrive();
            return;
        }

        const step = Math.min(this.walkSpeed * delta, dist);
        const nx = dx / dist;
        const nz = dz / dist;
        this.group.position.x += nx * step;
        this.group.position.z += nz * step;
        this.group.rotation.y = Math.atan2(dx, dz);

        const walkBob = Math.abs(Math.sin(this.stateTime * 8)) * 0.06;
        if (this._bodyRef) this._bodyRef.position.y = this._baseY.body + walkBob;
        if (this._headRef) this._headRef.position.y = this._baseY.head + walkBob;

        if (this._armsRef.left) {
            this._armsRef.left.rotation.x = Math.sin(this.stateTime * 8) * 0.4;
        }
        if (this._armsRef.right) {
            this._armsRef.right.rotation.x = -Math.sin(this.stateTime * 8) * 0.4;
        }
    }

    _applySittingPose() {
        const drop = 0.08;
        if (this._bodyRef) this._bodyRef.position.y = this._baseY.body - drop;
        if (this._headRef) this._headRef.position.y = this._baseY.head - drop;
        if (this._armsRef.left) this._armsRef.left.position.y = (this._baseY.leftArm ?? 0.55) - drop;
        if (this._armsRef.right) this._armsRef.right.position.y = (this._baseY.rightArm ?? 0.55) - drop;
        if (this._legsRef.left) {
            this._legsRef.left.rotation.x = -Math.PI / 2.2;
            this._legsRef.left.position.y = (this._baseY.leftLeg ?? 0.15) + 0.12;
            this._legsRef.left.position.z = 0.12;
        }
        if (this._legsRef.right) {
            this._legsRef.right.rotation.x = -Math.PI / 2.2;
            this._legsRef.right.position.y = (this._baseY.rightLeg ?? 0.15) + 0.12;
            this._legsRef.right.position.z = 0.12;
        }
        this.group.rotation.y = Math.PI;
    }

    _animateTyping(delta) {
        this._applySittingPose();
        if (this._armsRef.left) {
            this._armsRef.left.rotation.x = -0.7 + Math.sin(this.stateTime * 12) * 0.08;
        }
        if (this._armsRef.right) {
            this._armsRef.right.rotation.x = -0.7 + Math.cos(this.stateTime * 14) * 0.08;
        }
        if (this._headRef) {
            this._headRef.rotation.x = -0.1 + Math.sin(this.stateTime * 0.5) * 0.02;
        }
    }

    _animateReading(delta) {
        this._applySittingPose();
        if (this._headRef) {
            this._headRef.rotation.x = -0.15;
            this._headRef.rotation.y = Math.sin(this.stateTime * 0.8) * 0.1;
        }
    }

    _animateWaiting(delta) {
        const pulse = (Math.sin(this.stateTime * 3) + 1) * 0.5;
        if (this._bodyRef?.material) {
            this._bodyRef.material.emissiveIntensity = pulse * 0.3;
        }
        if (this._bodyRef) {
            this._bodyRef.position.x = Math.sin(this.stateTime * 0.8) * 0.03;
        }
    }

    _animateChatting(delta) {
        const gesture = Math.sin(this.stateTime * 2.5);
        if (this._armsRef.left) {
            this._armsRef.left.rotation.x = -0.3 + gesture * 0.25;
            this._armsRef.left.rotation.z = -0.15;
        }
        if (this._armsRef.right) {
            this._armsRef.right.rotation.x = -0.3 - gesture * 0.2;
            this._armsRef.right.rotation.z = 0.15;
        }
        if (this._headRef) {
            this._headRef.rotation.y = Math.sin(this.stateTime * 1.2) * 0.12;
            this._headRef.rotation.x = Math.sin(this.stateTime * 0.8) * 0.04;
        }
        const sway = Math.sin(this.stateTime * 1.0) * 0.008;
        if (this._bodyRef) this._bodyRef.position.y = this._baseY.body + sway;
    }

    _resetPose() {
        if (this._armsRef.left) {
            this._armsRef.left.rotation.set(0, 0, 0);
            this._armsRef.left.position.y = this._baseY.leftArm ?? 0.55;
        }
        if (this._armsRef.right) {
            this._armsRef.right.rotation.set(0, 0, 0);
            this._armsRef.right.position.y = this._baseY.rightArm ?? 0.55;
        }
        if (this._legsRef.left) {
            this._legsRef.left.rotation.set(0, 0, 0);
            this._legsRef.left.position.y = this._baseY.leftLeg ?? 0.15;
            this._legsRef.left.position.z = 0;
        }
        if (this._legsRef.right) {
            this._legsRef.right.rotation.set(0, 0, 0);
            this._legsRef.right.position.y = this._baseY.rightLeg ?? 0.15;
            this._legsRef.right.position.z = 0;
        }
        if (this._headRef) {
            this._headRef.rotation.set(0, 0, 0);
            this._headRef.position.y = this._baseY.head ?? 0.95;
        }
        if (this._bodyRef) {
            this._bodyRef.position.x = 0;
            this._bodyRef.position.y = this._baseY.body ?? 0.55;
            if (this._bodyRef.material) {
                this._bodyRef.material.emissiveIntensity = 0;
            }
        }
    }
}

import {
    Group, Mesh, SphereGeometry, BoxGeometry, MeshBasicMaterial,
    CanvasTexture, SpriteMaterial, Sprite, AdditiveBlending,
    Color, Vector3,
} from 'three';

const particlePool = [];

function getParticle(color = 0xffffff) {
    if (particlePool.length > 0) {
        const p = particlePool.pop();
        p.material.color.setHex(color);
        p.visible = true;
        return p;
    }
    const geom = new SphereGeometry(0.04, 4, 4);
    const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.8 });
    return new Mesh(geom, mat);
}

function releaseParticle(p) {
    p.visible = false;
    particlePool.push(p);
}

export class ParticleEmitter {
    constructor(scene) {
        this.scene = scene;
        this.particles = [];
    }

    emit(position, options = {}) {
        const { count = 8, color = 0x22c55e, spread = 0.5, lifetime = 1.5, speed = 1.5 } = options;
        for (let i = 0; i < count; i++) {
            const p = getParticle(color);
            p.position.copy(position);
            p.position.x += (Math.random() - 0.5) * spread * 0.3;
            p.position.z += (Math.random() - 0.5) * spread * 0.3;
            this.scene.add(p);
            this.particles.push({
                mesh: p,
                velocity: new Vector3(
                    (Math.random() - 0.5) * spread * speed,
                    Math.random() * speed * 1.5 + 0.5,
                    (Math.random() - 0.5) * spread * speed,
                ),
                lifetime,
                age: 0,
            });
        }
    }

    emitSuccess(position) {
        this.emit(position, { count: 12, color: 0x22c55e, spread: 0.6, lifetime: 1.2 });
    }

    emitFailure(position) {
        this.emit(position, { count: 8, color: 0xef4444, spread: 0.4, lifetime: 1.0, speed: 0.8 });
    }

    emitMemory(position) {
        this.emit(position, { count: 6, color: 0x8b5cf6, spread: 0.3, lifetime: 2.0, speed: 0.5 });
    }

    update(delta) {
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.age += delta;
            if (p.age >= p.lifetime) {
                this.scene.remove(p.mesh);
                releaseParticle(p.mesh);
                this.particles.splice(i, 1);
                continue;
            }
            const t = p.age / p.lifetime;
            p.mesh.position.add(p.velocity.clone().multiplyScalar(delta));
            p.velocity.y -= delta * 2;
            p.mesh.material.opacity = 1.0 - t;
            const scale = 1.0 - t * 0.5;
            p.mesh.scale.setScalar(scale);
        }
    }

    dispose() {
        this.particles.forEach((p) => {
            this.scene.remove(p.mesh);
            releaseParticle(p.mesh);
        });
        this.particles = [];
    }
}

export class SpeechBubble {
    constructor(scene) {
        this.scene = scene;
        this.bubbles = new Map();
    }

    show(agentId, text, targetGroup, options = {}) {
        const { duration = 4, color = '#e0e8ff', bgColor = 'rgba(15,20,40,0.92)', thought = false } = options;

        this.hide(agentId);

        const canvas = document.createElement('canvas');
        canvas.width = 320;
        canvas.height = 96;
        const ctx = canvas.getContext('2d');

        ctx.fillStyle = bgColor;
        ctx.beginPath();
        ctx.roundRect(8, 4, 304, 64, 14);
        ctx.fill();

        if (thought) {
            ctx.fillStyle = bgColor;
            ctx.beginPath();
            ctx.ellipse(160, 76, 6, 4, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(155, 86, 3.5, 2.5, 0, 0, Math.PI * 2);
            ctx.fill();
        } else {
            ctx.beginPath();
            ctx.moveTo(148, 68);
            ctx.lineTo(160, 80);
            ctx.lineTo(172, 68);
            ctx.fillStyle = bgColor;
            ctx.fill();
        }

        ctx.strokeStyle = thought ? 'rgba(140,160,255,0.35)' : 'rgba(100,140,255,0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.roundRect(8, 4, 304, 64, 14);
        ctx.stroke();

        ctx.font = '15px system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = color;
        const truncated = text.length > 40 ? text.slice(0, 37) + '...' : text;
        ctx.fillText(truncated, 160, 36);

        const texture = new CanvasTexture(canvas);
        const mat = new SpriteMaterial({ map: texture, depthTest: false, transparent: true });
        const sprite = new Sprite(mat);
        sprite.scale.set(2.0, 0.6, 1);
        sprite.position.set(0, 1.75, 0);

        if (targetGroup) {
            targetGroup.add(sprite);
        } else {
            this.scene.add(sprite);
        }

        this.bubbles.set(agentId, {
            sprite,
            parent: targetGroup || this.scene,
            age: 0,
            duration,
            fadeStart: duration * 0.75,
        });
    }

    hide(agentId) {
        const bubble = this.bubbles.get(agentId);
        if (bubble) {
            bubble.parent.remove(bubble.sprite);
            bubble.sprite.material.dispose();
            this.bubbles.delete(agentId);
        }
    }

    update(delta) {
        this.bubbles.forEach((bubble, agentId) => {
            bubble.age += delta;
            if (bubble.age >= bubble.duration) {
                this.hide(agentId);
                return;
            }
            if (bubble.age > bubble.fadeStart) {
                const fadeT = (bubble.age - bubble.fadeStart) / (bubble.duration - bubble.fadeStart);
                bubble.sprite.material.opacity = 1.0 - fadeT;
            }
            bubble.sprite.position.y = 1.75 + Math.sin(bubble.age * 2) * 0.02;
        });
    }

    dispose() {
        this.bubbles.forEach((_, agentId) => this.hide(agentId));
    }
}

export class AmbientAnimations {
    constructor(scene) {
        this.scene = scene;
        this.time = 0;
        this._floatingObjects = [];
    }

    registerFloater(mesh, amplitude = 0.02, frequency = 1.5) {
        this._floatingObjects.push({
            mesh,
            baseY: mesh.position.y,
            amplitude,
            frequency,
            phase: Math.random() * Math.PI * 2,
        });
    }

    update(delta) {
        this.time += delta;
        this._floatingObjects.forEach((f) => {
            f.mesh.position.y = f.baseY + Math.sin(this.time * f.frequency + f.phase) * f.amplitude;
        });
    }

    dispose() {
        this._floatingObjects = [];
    }
}

const OUTPUT_EVENT_TYPES = new Set(['stdout', 'stderr']);
const STREAM_ENVELOPE_TYPES = new Set(['stream_event', 'assistant', 'user', 'result']);
const STRUCTURED_ENVELOPE_MARKER_PATTERN = /"type"\s*:\s*"(?:stream_event|assistant|user|result)"|"session_id"\s*:|"parent_tool_use_id"\s*:|\[\d+\s+(?:stdout|stderr|lifecycle)\]/;
const ENVELOPE_CARRY_LIMIT = 32_768;
const DEDUPE_WINDOW_EVENTS = 80;
const DEDUPE_MIN_CHARS = 24;
const ESCAPED_LINE_BREAK_PATTERN = /\\r\\n|\\n|\\r/g;
const LINE_NUMBERED_SNIPPET_LINE_PATTERN = /^\s*(\d+)\s*(?:→|->|=>)\s?(.*)$/u;
const LINE_NUMBERED_PREFIX_PATTERN = /^\s*\d+\s*\|\s?/u;
const LINE_NUMBERED_PREFIX_CAPTURE_PATTERN = /^\s*(\d+)\s*\|\s?/u;
const MCP_CONNECTION_REFUSED_PATTERN = /rmcp::transport::worker[\s\S]{0,1800}?transport channel closed[\s\S]{0,1800}?(https?:\/\/[^\s"']+\/mcp)[\s\S]{0,1800}?connection refused/i;

const stringifyPayload = (payload) => {
    if (typeof payload === 'string') {
        return payload;
    }

    if (payload === null || payload === undefined) {
        return '';
    }

    if (typeof payload === 'object') {
        try {
            return JSON.stringify(payload);
        } catch {
            return '[unprintable payload]';
        }
    }

    return String(payload);
};

const parseJson = (raw) => {
    if (typeof raw !== 'string') {
        return null;
    }

    const trimmed = raw.trim();
    if (trimmed === '') {
        return null;
    }

    const first = trimmed[0];
    if (first !== '{' && first !== '[') {
        return null;
    }

    try {
        return JSON.parse(trimmed);
    } catch {
        return null;
    }
};

const parseSequentialJsonPayload = (raw) => {
    if (typeof raw !== 'string') {
        return null;
    }

    const trimmed = raw.trim();
    if (trimmed === '') {
        return null;
    }

    const first = trimmed[0];
    if (first !== '{' && first !== '[') {
        return null;
    }

    const { parsedValues, remainder, hasIncompleteJson } = extractJsonObjects(trimmed);
    if (hasIncompleteJson || parsedValues.length < 2) {
        return null;
    }

    if (String(remainder ?? '').trim() !== '') {
        return null;
    }

    return parsedValues.map((value) => JSON.stringify(value, null, 2)).join('\n\n');
};

const parseChunkedTextPayload = (raw) => {
    const parsed = parseJson(raw);
    if (!isRecord(parsed) || typeof parsed.text !== 'string' || typeof parsed.continuation !== 'boolean') {
        return null;
    }

    return {
        text: parsed.text,
        continuation: parsed.continuation,
    };
};

const decodeEscapedLineBreaks = (value) => {
    if (typeof value !== 'string' || value === '') {
        return value;
    }

    const escapedBreaks = value.match(ESCAPED_LINE_BREAK_PATTERN);
    if (!Array.isArray(escapedBreaks) || escapedBreaks.length === 0) {
        return value;
    }

    const looksLikeStructuredEscapedBlock = /\\n\s{0,4}(?:\d+\s*(?:→|->|=>)|#{1,6}\s|[-*]\s|\d+\.\s)/u.test(value);
    if (escapedBreaks.length < 2 && !looksLikeStructuredEscapedBlock && !value.includes('→\\n')) {
        return value;
    }

    return value
        .replace(/\\r\\n/g, '\n')
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\n')
        .replace(/\\t/g, '\t')
        .replace(/\\"/g, '"');
};

const normalizeLineNumberedSnippet = (value) => {
    if (typeof value !== 'string' || value.trim() === '') {
        return value;
    }

    const lines = value.split('\n');
    let transformed = 0;

    const normalizedLines = lines.map((line) => {
        const match = line.match(LINE_NUMBERED_SNIPPET_LINE_PATTERN);
        if (!match) {
            return line;
        }

        transformed += 1;
        const lineNumber = String(match[1] ?? '').trim();
        const content = String(match[2] ?? '').replace(/\s+$/g, '');

        return content === '' ? `${lineNumber} |` : `${lineNumber} | ${content}`;
    });

    if (transformed < 3) {
        return value;
    }

    const cleanedLines = normalizedLines.filter((line) => line.trim() !== '→');
    return cleanedLines.join('\n');
};

const stripLineNumberPrefixes = (value) => {
    if (typeof value !== 'string' || value.trim() === '') {
        return value;
    }

    const lines = value.split('\n');
    let transformed = 0;

    const stripped = lines.map((line) => {
        if (!LINE_NUMBERED_PREFIX_PATTERN.test(line)) {
            return line;
        }

        transformed += 1;
        return line.replace(LINE_NUMBERED_PREFIX_PATTERN, '');
    });

    if (transformed < 3) {
        return value;
    }

    return stripped.join('\n');
};

const summarizeReadExcerptPayload = (value, eventType) => {
    if (eventType !== 'stdout' || typeof value !== 'string' || value.trim() === '') {
        return null;
    }

    const lines = value.split('\n');
    const lineNumbers = lines
        .map((line) => {
            const match = line.match(LINE_NUMBERED_PREFIX_CAPTURE_PATTERN);
            return match ? Number(match[1]) : null;
        })
        .filter((lineNumber) => Number.isFinite(lineNumber));

    if (lineNumbers.length < 8) {
        return null;
    }

    const markdownCandidate = stripLineNumberPrefixes(value);
    if (!looksLikeMarkdown(markdownCandidate)) {
        return null;
    }

    const firstLine = Math.min(...lineNumbers);
    const lastLine = Math.max(...lineNumbers);

    if (Number.isFinite(firstLine) && Number.isFinite(lastLine) && lastLine >= firstLine) {
        return `Read excerpt omitted (${lineNumbers.length} lines, source lines ${firstLine}-${lastLine})`;
    }

    return `Read excerpt omitted (${lineNumbers.length} lines)`;
};

const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isStructuredEnvelopeObject = (value) => isRecord(value) && STREAM_ENVELOPE_TYPES.has(String(value.type ?? '').trim());

const hasStructuredEnvelopeMarkers = (value) => {
    if (typeof value !== 'string') {
        return false;
    }

    return STRUCTURED_ENVELOPE_MARKER_PATTERN.test(value);
};

const readJsonValueWindow = (text, startIndex) => {
    const opening = text[startIndex];
    if (opening !== '{' && opening !== '[') {
        return { status: 'invalid', end: startIndex + 1 };
    }

    const stack = [opening];
    let inString = false;
    let escaped = false;

    for (let index = startIndex + 1; index < text.length; index += 1) {
        const character = text[index];

        if (inString) {
            if (escaped) {
                escaped = false;
                continue;
            }

            if (character === '\\') {
                escaped = true;
                continue;
            }

            if (character === '"') {
                inString = false;
            }

            continue;
        }

        if (character === '"') {
            inString = true;
            continue;
        }

        if (character === '{' || character === '[') {
            stack.push(character);
            continue;
        }

        if (character === '}' || character === ']') {
            const current = stack[stack.length - 1];
            const isMatch = (character === '}' && current === '{')
                || (character === ']' && current === '[');

            if (!isMatch) {
                return { status: 'invalid', end: startIndex + 1 };
            }

            stack.pop();

            if (stack.length === 0) {
                return { status: 'complete', end: index + 1 };
            }
        }
    }

    return { status: 'incomplete', end: text.length };
};

const extractJsonObjects = (text) => {
    if (typeof text !== 'string' || text === '') {
        return {
            parsedValues: [],
            remainder: '',
            hasIncompleteJson: false,
        };
    }

    const parsedValues = [];
    let cursor = 0;
    let remainder = '';
    let hasIncompleteJson = false;

    while (cursor < text.length) {
        const relativeStart = text.slice(cursor).search(/[{\[]/);
        if (relativeStart === -1) {
            break;
        }

        const startIndex = cursor + relativeStart;
        const window = readJsonValueWindow(text, startIndex);

        if (window.status === 'incomplete') {
            remainder = text.slice(startIndex);
            hasIncompleteJson = true;
            break;
        }

        if (window.status === 'invalid') {
            cursor = startIndex + 1;
            continue;
        }

        const candidate = text.slice(startIndex, window.end);

        try {
            parsedValues.push(JSON.parse(candidate));
            cursor = window.end;
        } catch {
            cursor = startIndex + 1;
        }
    }

    return {
        parsedValues,
        remainder,
        hasIncompleteJson,
    };
};

const writeEnvelopeCarry = (state, eventType, value) => {
    if (!(state.envelopeCarryByType instanceof Map)) {
        return;
    }

    const normalized = String(value ?? '');
    if (normalized.trim() === '') {
        state.envelopeCarryByType.delete(eventType);
        return;
    }

    state.envelopeCarryByType.set(eventType, normalized.slice(-ENVELOPE_CARRY_LIMIT));
};

const buildPrefix = (sequence, eventType) => {
    if (Number.isFinite(sequence) && sequence > 0) {
        return `[${sequence} ${eventType}]`;
    }

    return `[${eventType}]`;
};

const buildEntryContext = (entry) => {
    const eventType = String(entry?.event_type ?? '').trim() || 'event';
    const sequence = Number(entry?.sequence ?? 0);
    const payloadRaw = stringifyPayload(entry?.payload);
    const fallbackTimestamp = String(entry?.event_ts ?? entry?.created_at ?? '').trim() || null;
    const key = String(entry?.id ?? `${sequence}:${eventType}`);
    const reasoningStep = entry?.reasoning_step ?? null;

    return {
        entry,
        eventType,
        sequence,
        payloadRaw,
        fallbackTimestamp,
        key,
        prefix: buildPrefix(sequence, eventType),
        reasoningStep,
    };
};

const formatLifecycleSummary = (payloadObject, fallbackTimestamp = null) => {
    if (!payloadObject || typeof payloadObject !== 'object' || Array.isArray(payloadObject)) {
        return null;
    }

    const type = String(payloadObject.type ?? '').trim().toLowerCase();
    if (type === 'state_transition') {
        const from = String(payloadObject.from ?? '').trim();
        const to = String(payloadObject.to ?? '').trim();
        const at = String(payloadObject.at ?? fallbackTimestamp ?? '').trim();
        const pid = payloadObject.pid;
        const exitCode = payloadObject.exit_code;
        const signal = payloadObject.signal;

        const parts = [];
        if (from !== '' && to !== '') {
            parts.push(`${from} -> ${to}`);
        } else if (to !== '') {
            parts.push(`state -> ${to}`);
        } else if (from !== '') {
            parts.push(`from ${from}`);
        } else {
            parts.push('state transition');
        }

        if (at !== '') {
            parts.push(`at ${at}`);
        }

        if (Number.isFinite(Number(pid))) {
            parts.push(`pid ${pid}`);
        }

        if (exitCode !== null && exitCode !== undefined && exitCode !== '') {
            parts.push(`exit ${exitCode}`);
        }

        if (signal !== null && signal !== undefined && signal !== '') {
            parts.push(`signal ${signal}`);
        }

        return parts.join(' | ');
    }

    if (type === 'heartbeat') {
        const elapsedSeconds = Number(payloadObject.elapsed_seconds);
        const at = String(payloadObject.at ?? fallbackTimestamp ?? '').trim();
        const parts = ['heartbeat'];

        if (Number.isFinite(elapsedSeconds) && elapsedSeconds >= 0) {
            parts.push(`${elapsedSeconds}s elapsed`);
        }

        if (at !== '') {
            parts.push(`at ${at}`);
        }

        return parts.join(' | ');
    }

    if (type === 'rate_limit_detected') {
        const resetAt = String(payloadObject.reset_at ?? '').trim();
        const timezone = String(payloadObject.timezone ?? '').trim();
        const at = String(payloadObject.at ?? fallbackTimestamp ?? '').trim();
        const parts = ['Rate limit detected'];

        if (resetAt !== '') {
            try {
                const resetDate = new Date(resetAt);
                const timeStr = resetDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                const tzSuffix = timezone && timezone !== 'UTC' ? ` (${timezone})` : '';
                parts.push(`resets ${timeStr}${tzSuffix}`);
            } catch {
                parts.push(`resets ${resetAt}`);
            }
        }

        if (at !== '' && !resetAt) {
            parts.push(`at ${at}`);
        }

        return parts.join(' | ');
    }

    if (type === 'redaction_notice') {
        const segments = Number(payloadObject.replaced_segments ?? 0);
        return segments > 0 ? `Redacted ${segments} sensitive segment${segments !== 1 ? 's' : ''}` : 'Redaction applied';
    }

    if (type === 'truncation_notice') {
        const msg = String(payloadObject.message ?? '').trim();
        return msg || 'Output truncated (5MB limit)';
    }

    return null;
};

const normalizeOutputPayload = (eventType, rawPayload) => {
    if (!OUTPUT_EVENT_TYPES.has(eventType)) {
        return rawPayload;
    }

    let normalizedPayload = rawPayload;
    const parsed = parseJson(rawPayload);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && typeof parsed.text === 'string') {
        normalizedPayload = parsed.text;
    }

    normalizedPayload = decodeEscapedLineBreaks(normalizedPayload);
    normalizedPayload = normalizeLineNumberedSnippet(normalizedPayload);

    return normalizedPayload;
};

const looksLikeMarkdown = (value) => {
    if (typeof value !== 'string') {
        return false;
    }

    const text = value.trim();
    if (text === '') {
        return false;
    }

    if (!text.includes('\n') && text.length < 120) {
        return false;
    }

    return /(^|\n)\s*(#{1,6}\s+|[-*]\s+|\d+\.\s+|>\s+|```|~~~|\|.+\|)/m.test(text)
        || /(\*\*[^*]+\*\*)|(`[^`]+`)|(\[[^\]]+\]\([^)]+\))/m.test(text);
};

const makeFormattedEntry = ({
    key,
    prefix,
    payload,
    tone = 'plain',
    format = 'pre',
    reasoningStep = null,
}) => ({
    key,
    prefix,
    payload,
    tone,
    format,
    reasoningStep,
});

const normalizeTextForDeduping = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();

const isDedupableEntry = (entry) => {
    if (!isRecord(entry)) {
        return false;
    }

    const tone = String(entry.tone ?? '').trim();
    if (!['plain', 'markdown'].includes(tone)) {
        return false;
    }

    const normalized = normalizeTextForDeduping(entry.payload);
    if (normalized.length < DEDUPE_MIN_CHARS) {
        return false;
    }

    if (normalized.startsWith('Tool call:')) {
        return false;
    }

    return true;
};

const dedupeFormattedEntries = (entries) => {
    if (!Array.isArray(entries) || entries.length === 0) {
        return [];
    }

    const lastSeenIndexBySignature = new Map();

    return entries.filter((entry, index) => {
        if (!isDedupableEntry(entry)) {
            return true;
        }

        const normalized = normalizeTextForDeduping(entry.payload);
        const signature = `${String(entry.tone ?? 'plain').trim()}::${normalized}`;
        const previousIndex = lastSeenIndexBySignature.get(signature);

        if (typeof previousIndex === 'number' && (index - previousIndex) <= DEDUPE_WINDOW_EVENTS) {
            return false;
        }

        lastSeenIndexBySignature.set(signature, index);

        if (lastSeenIndexBySignature.size > 1024) {
            Array.from(lastSeenIndexBySignature.entries()).forEach(([key, seenIndex]) => {
                if ((index - seenIndex) > DEDUPE_WINDOW_EVENTS) {
                    lastSeenIndexBySignature.delete(key);
                }
            });
        }

        return true;
    });
};

const summarizeToolUseResult = (toolUseResult) => {
    if (!isRecord(toolUseResult)) {
        return [];
    }

    const messages = [];

    if (isRecord(toolUseResult.file)) {
        const filePath = String(toolUseResult.file.filePath ?? '').trim();
        const numLines = Number(toolUseResult.file.numLines ?? NaN);

        if (filePath !== '') {
            if (Number.isFinite(numLines) && numLines > 0) {
                messages.push(`Read: ${filePath} (${numLines} lines)`);
            } else {
                messages.push(`Read: ${filePath}`);
            }
        }
    }

    if (Array.isArray(toolUseResult.filenames)) {
        const count = toolUseResult.filenames.length;
        messages.push(`Glob matched ${count} file${count === 1 ? '' : 's'}`);
    }

    if (Array.isArray(toolUseResult.newTodos)) {
        messages.push(`Todo list updated (${toolUseResult.newTodos.length} item${toolUseResult.newTodos.length === 1 ? '' : 's'})`);
    }

    if (messages.length === 0 && typeof toolUseResult.type === 'string' && String(toolUseResult.type).trim() !== '') {
        messages.push(`Tool result: ${String(toolUseResult.type).trim()}`);
    }

    return messages;
};

const getStreamSessionId = (payloadObject) => String(payloadObject?.session_id ?? '').trim() || 'stream';

const getStreamBufferKey = (sessionId, eventType, index) => `${sessionId}:${eventType}:${index}`;

const flushTextBuffer = (formattedEntries, streamTextBuffers, streamBufferKey, { partial = false, state = null } = {}) => {
    const buffer = streamTextBuffers.get(streamBufferKey);
    if (!buffer) {
        return;
    }

    const text = String(buffer.text ?? '');
    const trimmed = text.trim();
    if (trimmed === '') {
        streamTextBuffers.delete(streamBufferKey);
        return;
    }

    const normalizedText = normalizeOutputPayload(buffer.eventType, text);
    const readExcerptSummary = summarizeReadExcerptPayload(normalizedText, buffer.eventType);

    if (readExcerptSummary !== null) {
        formattedEntries.push(makeFormattedEntry({
            key: partial ? `${buffer.key}:partial` : buffer.key,
            prefix: buffer.prefix,
            payload: readExcerptSummary,
            tone: 'structured',
            format: 'pre',
        }));

        if (state && state.lastTextBySession instanceof Map) {
            state.lastTextBySession.set(buffer.sessionId, readExcerptSummary);
        }

        streamTextBuffers.delete(streamBufferKey);
        return;
    }

    const markdownPayload = stripLineNumberPrefixes(normalizedText);
    const payload = partial ? `${markdownPayload} …` : markdownPayload;
    const markdown = looksLikeMarkdown(markdownPayload);

    formattedEntries.push(makeFormattedEntry({
        key: partial ? `${buffer.key}:partial` : buffer.key,
        prefix: buffer.prefix,
        payload,
        tone: buffer.eventType === 'stderr' ? 'stderr' : (markdown ? 'markdown' : 'plain'),
        format: markdown ? 'markdown' : 'pre',
    }));

    if (state && state.lastTextBySession instanceof Map) {
        state.lastTextBySession.set(buffer.sessionId, trimmed);
    }

    streamTextBuffers.delete(streamBufferKey);
};

const handleStreamEventPayload = (context, payloadObject, formattedEntries, state) => {
    const event = isRecord(payloadObject.event) ? payloadObject.event : null;
    if (!event) {
        return false;
    }

    const streamEventType = String(event.type ?? '').trim();
    const sessionId = getStreamSessionId(payloadObject);

    if (streamEventType === 'content_block_start') {
        const index = Number(event.index ?? 0);
        const contentBlock = isRecord(event.content_block) ? event.content_block : null;
        const blockType = String(contentBlock?.type ?? '').trim();

        if (blockType === 'text') {
            const bufferKey = getStreamBufferKey(sessionId, context.eventType, index);
            state.streamTextBuffers.set(bufferKey, {
                key: `${context.key}:stream-text:${index}`,
                prefix: context.prefix,
                eventType: context.eventType,
                sessionId,
                text: '',
            });

            return true;
        }

        if (blockType === 'tool_use') {
            const toolName = String(contentBlock?.name ?? '').trim();
            if (toolName !== '') {
                formattedEntries.push(makeFormattedEntry({
                    key: `${context.key}:tool:${index}`,
                    prefix: context.prefix,
                    payload: `Tool call: ${toolName}`,
                    tone: 'structured',
                    format: 'pre',
                }));
            }

            return true;
        }

        return true;
    }

    if (streamEventType === 'content_block_delta') {
        const index = Number(event.index ?? 0);
        const delta = isRecord(event.delta) ? event.delta : null;
        const deltaType = String(delta?.type ?? '').trim();
        const bufferKey = getStreamBufferKey(sessionId, context.eventType, index);

        if (deltaType === 'text_delta') {
            const textPart = String(delta?.text ?? '');
            const existing = state.streamTextBuffers.get(bufferKey) ?? {
                key: `${context.key}:stream-text:${index}`,
                prefix: context.prefix,
                eventType: context.eventType,
                sessionId,
                text: '',
            };

            existing.text += textPart;
            state.streamTextBuffers.set(bufferKey, existing);
            return true;
        }

        if (deltaType === 'input_json_delta') {
            return true;
        }

        if (deltaType !== '') {
            return true;
        }

        return false;
    }

    if (streamEventType === 'content_block_stop') {
        const index = Number(event.index ?? 0);
        const bufferKey = getStreamBufferKey(sessionId, context.eventType, index);
        flushTextBuffer(formattedEntries, state.streamTextBuffers, bufferKey, { state });
        return true;
    }

    if (streamEventType === 'message_stop') {
        Array.from(state.streamTextBuffers.keys())
            .filter((bufferKey) => bufferKey.startsWith(`${sessionId}:${context.eventType}:`))
            .forEach((bufferKey) => {
                flushTextBuffer(formattedEntries, state.streamTextBuffers, bufferKey, { state });
            });

        return true;
    }

    if (streamEventType === 'message_start' || streamEventType === 'message_delta') {
        return true;
    }

    return false;
};

const handleAssistantPayload = (context, payloadObject, formattedEntries, state) => {
    const message = isRecord(payloadObject.message) ? payloadObject.message : null;
    const blocks = Array.isArray(message?.content) ? message.content : [];
    const sessionId = getStreamSessionId(payloadObject);

    if (blocks.length === 0) {
        return true;
    }

    blocks.forEach((block, index) => {
        if (!isRecord(block)) {
            return;
        }

        const blockType = String(block.type ?? '').trim();

        if (blockType === 'text') {
            const text = String(block.text ?? '');
            const trimmed = text.trim();
            if (trimmed === '') {
                return;
            }

            if (state.lastTextBySession.get(sessionId) === trimmed) {
                return;
            }

            const markdown = looksLikeMarkdown(text);
            formattedEntries.push(makeFormattedEntry({
                key: `${context.key}:assistant:${index}`,
                prefix: context.prefix,
                payload: text,
                tone: markdown ? 'markdown' : 'plain',
                format: markdown ? 'markdown' : 'pre',
            }));
            state.lastTextBySession.set(sessionId, trimmed);
            return;
        }

        if (blockType === 'tool_use') {
            const toolName = String(block.name ?? '').trim();
            if (toolName === '') {
                return;
            }

            formattedEntries.push(makeFormattedEntry({
                key: `${context.key}:assistant-tool:${index}`,
                prefix: context.prefix,
                payload: `Tool call: ${toolName}`,
                tone: 'structured',
                format: 'pre',
            }));
        }
    });

    return true;
};

const handleUserPayload = (context, payloadObject, formattedEntries) => {
    const summaryMessages = summarizeToolUseResult(payloadObject.tool_use_result);

    if (summaryMessages.length > 0) {
        summaryMessages.forEach((summary, index) => {
            formattedEntries.push(makeFormattedEntry({
                key: `${context.key}:tool-result:${index}`,
                prefix: context.prefix,
                payload: summary,
                tone: 'structured',
                format: 'pre',
            }));
        });

        return true;
    }

    const message = isRecord(payloadObject.message) ? payloadObject.message : null;
    const contentBlocks = Array.isArray(message?.content) ? message.content : [];
    const shortTextBlocks = contentBlocks
        .filter((block) => isRecord(block) && String(block.type ?? '').trim() === 'text')
        .map((block) => String(block.text ?? '').trim())
        .filter((text) => text !== '' && text.length <= 240);

    if (shortTextBlocks.length > 0) {
        shortTextBlocks.forEach((text, index) => {
            formattedEntries.push(makeFormattedEntry({
                key: `${context.key}:user-text:${index}`,
                prefix: context.prefix,
                payload: text,
                tone: 'plain',
                format: 'pre',
            }));
        });

        return true;
    }

    return true;
};

const handleResultPayload = (context, payloadObject, formattedEntries) => {
    if (!isRecord(payloadObject.result)) {
        return true;
    }

    const status = String(payloadObject.result.status ?? '').trim();
    const duration = Number(payloadObject.result.duration_ms ?? NaN);

    const details = [];
    if (status !== '') {
        details.push(`status: ${status}`);
    }
    if (Number.isFinite(duration) && duration >= 0) {
        details.push(`duration: ${duration}ms`);
    }

    if (details.length > 0) {
        formattedEntries.push(makeFormattedEntry({
            key: `${context.key}:result`,
            prefix: context.prefix,
            payload: `Result (${details.join(', ')})`,
            tone: 'structured',
            format: 'pre',
        }));
    }

    return true;
};

const handleStructuredEnvelope = (context, payloadObject, formattedEntries, state) => {
    const envelopeType = String(payloadObject.type ?? '').trim();

    if (!STREAM_ENVELOPE_TYPES.has(envelopeType)) {
        return false;
    }

    if (envelopeType === 'stream_event') {
        return handleStreamEventPayload(context, payloadObject, formattedEntries, state);
    }

    if (envelopeType === 'assistant') {
        return handleAssistantPayload(context, payloadObject, formattedEntries, state);
    }

    if (envelopeType === 'user') {
        return handleUserPayload(context, payloadObject, formattedEntries);
    }

    if (envelopeType === 'result') {
        return handleResultPayload(context, payloadObject, formattedEntries);
    }

    return false;
};

const handleStructuredEnvelopeFragments = (context, normalizedPayload, formattedEntries, state) => {
    if (!OUTPUT_EVENT_TYPES.has(context.eventType)) {
        return false;
    }

    const eventType = context.eventType;
    const existingCarry = String(state.envelopeCarryByType.get(eventType) ?? '');
    const rawPayload = typeof normalizedPayload === 'string' ? normalizedPayload : String(normalizedPayload ?? '');
    const shouldInspect = existingCarry !== '' || hasStructuredEnvelopeMarkers(rawPayload);

    if (!shouldInspect) {
        return false;
    }

    const combined = `${existingCarry}${rawPayload}`;
    const { parsedValues, remainder, hasIncompleteJson } = extractJsonObjects(combined);

    let handled = false;

    parsedValues.forEach((parsedValue, index) => {
        const fragmentContext = {
            ...context,
            key: `${context.key}:fragment:${index}`,
        };

        if (isStructuredEnvelopeObject(parsedValue)) {
            const handledEnvelope = handleStructuredEnvelope(fragmentContext, parsedValue, formattedEntries, state);
            handled = handled || handledEnvelope;
            return;
        }

        const contentSnapshot = extractContentSnapshotFromPayload(parsedValue);
        if (contentSnapshot !== null) {
            formattedEntries.push(makeFormattedEntry({
                key: fragmentContext.key,
                prefix: fragmentContext.prefix,
                payload: contentSnapshot,
                tone: 'plain',
                format: 'pre',
            }));
            handled = true;
        }
    });

    if (hasIncompleteJson) {
        writeEnvelopeCarry(state, eventType, remainder);
    } else {
        writeEnvelopeCarry(state, eventType, '');
    }

    return handled || hasIncompleteJson || existingCarry !== '' || hasStructuredEnvelopeMarkers(rawPayload);
};

const stitchChunkedOutputEntries = (entries) => {
    if (!Array.isArray(entries) || entries.length === 0) {
        return [];
    }

    const stitched = [];
    let pending = null;

    const flushPending = () => {
        if (!pending) {
            return;
        }

        stitched.push(pending);
        pending = null;
    };

    entries.forEach((entry) => {
        const rawPayload = stringifyPayload(entry?.payload);
        const chunk = parseChunkedTextPayload(rawPayload);

        if (!chunk) {
            flushPending();
            stitched.push(entry);
            return;
        }

        if (!chunk.continuation) {
            flushPending();
            pending = {
                ...entry,
                payload: chunk.text,
            };

            return;
        }

        if (!pending || String(pending?.event_type ?? '') !== String(entry?.event_type ?? '')) {
            flushPending();
            stitched.push({
                ...entry,
                payload: chunk.text,
            });
            return;
        }

        pending = {
            ...pending,
            payload: `${String(pending.payload ?? '')}${chunk.text}`,
        };
    });

    flushPending();

    return stitched;
};

export const formatAgentRunEventEntry = (entry) => {
    const context = buildEntryContext(entry);

    if (context.eventType === 'lifecycle') {
        const lifecyclePayload = parseJson(context.payloadRaw);
        const lifecycleSummary = formatLifecycleSummary(lifecyclePayload, context.fallbackTimestamp);

        if (lifecycleSummary) {
            return makeFormattedEntry({
                key: context.key,
                prefix: context.prefix,
                payload: lifecycleSummary,
                tone: 'lifecycle',
                format: 'pre',
                reasoningStep: context.reasoningStep,
            });
        }

        if (lifecyclePayload !== null) {
            const summary = summarizeUnknownJsonPayload(lifecyclePayload);
            if (summary !== null) {
                return makeFormattedEntry({
                    key: context.key,
                    prefix: context.prefix,
                    payload: summary,
                    tone: 'lifecycle',
                    format: 'pre',
                    reasoningStep: context.reasoningStep,
                });
            }
            return null;
        }
    }

    const normalizedPayload = normalizeOutputPayload(context.eventType, context.payloadRaw);
    const parsedPayload = parseJson(normalizedPayload);

    if (parsedPayload !== null) {
        const contentSnapshot = extractContentSnapshotFromPayload(parsedPayload);
        if (contentSnapshot !== null) {
            return makeFormattedEntry({
                key: context.key,
                prefix: context.prefix,
                payload: contentSnapshot,
                tone: context.eventType === 'stderr' ? 'stderr' : 'plain',
                format: 'pre',
                reasoningStep: context.reasoningStep,
            });
        }
        const envelopeSummary = formatStructuredEnvelopeSummary(parsedPayload);
        if (envelopeSummary !== null) {
            return makeFormattedEntry({
                key: context.key,
                prefix: context.prefix,
                payload: envelopeSummary,
                tone: 'structured',
                format: 'pre',
                reasoningStep: context.reasoningStep,
            });
        }
        const summary = summarizeUnknownJsonPayload(parsedPayload);
        if (summary !== null) {
            return makeFormattedEntry({
                key: context.key,
                prefix: context.prefix,
                payload: summary,
                tone: context.eventType === 'stderr' ? 'stderr' : 'structured',
                format: 'pre',
                reasoningStep: context.reasoningStep,
            });
        }
        return null;
    }

    // Multi-line JSON: payload may contain newline-separated JSON objects
    // that fail single parseJson() but can be individually formatted.
    if (normalizedPayload.includes('\n') && normalizedPayload.trimStart().startsWith('{')) {
        const lines = normalizedPayload.split('\n').filter((l) => l.trim() !== '');
        const summaries = [];
        for (const line of lines) {
            const lineJson = parseJson(line.trim());
            if (lineJson === null) continue;
            const snap = extractContentSnapshotFromPayload(lineJson);
            if (snap !== null) { summaries.push(snap); continue; }
            const env = formatStructuredEnvelopeSummary(lineJson);
            if (env !== null) { summaries.push(env); continue; }
            const unk = summarizeUnknownJsonPayload(lineJson);
            if (unk !== null) summaries.push(unk);
        }
        if (summaries.length > 0) {
            return makeFormattedEntry({
                key: context.key,
                prefix: context.prefix,
                payload: summaries.join('\n'),
                tone: 'structured',
                format: 'pre',
                reasoningStep: context.reasoningStep,
            });
        }
    }

    const readExcerptSummary = summarizeReadExcerptPayload(normalizedPayload, context.eventType);
    if (readExcerptSummary !== null) {
        return makeFormattedEntry({
            key: context.key,
            prefix: context.prefix,
            payload: readExcerptSummary,
            tone: 'structured',
            format: 'pre',
            reasoningStep: context.reasoningStep,
        });
    }

    const markdownCandidate = stripLineNumberPrefixes(normalizedPayload);

    if ((context.eventType === 'stdout' || context.eventType === 'stderr') && looksLikeMarkdown(markdownCandidate)) {
        return makeFormattedEntry({
            key: context.key,
            prefix: context.prefix,
            payload: markdownCandidate,
            tone: context.eventType === 'stderr' ? 'stderr' : 'markdown',
            format: 'markdown',
            reasoningStep: context.reasoningStep,
        });
    }

    if (NOISE_PAYLOAD_MARKERS.test(normalizedPayload)) {
        return null;
    }

    return makeFormattedEntry({
        key: context.key,
        prefix: context.prefix,
        payload: normalizedPayload,
        tone: context.eventType === 'stderr' ? 'stderr' : 'plain',
        format: 'pre',
        reasoningStep: context.reasoningStep,
    });
};

export const formatAgentRunEventEntries = (entries) => {
    if (!Array.isArray(entries)) {
        return [];
    }

    const stitchedEntries = stitchChunkedOutputEntries(entries);
    const formattedEntries = [];
    const state = {
        streamTextBuffers: new Map(),
        lastTextBySession: new Map(),
        envelopeCarryByType: new Map(),
    };

    stitchedEntries.forEach((entry) => {
        const context = buildEntryContext(entry);

        if (context.eventType === 'lifecycle') {
            const lifecycleEntry = formatAgentRunEventEntry(entry);
            if (String(lifecycleEntry?.payload ?? '').trim() !== '') {
                formattedEntries.push(lifecycleEntry);
            }
            return;
        }

        const normalizedPayload = normalizeOutputPayload(context.eventType, context.payloadRaw);
        const { parsedValues } = extractJsonObjects(normalizedPayload);

        if (parsedValues.length > 1) {
            let added = false;
            parsedValues.forEach((parsedValue, fragIndex) => {
                const fragContext = { ...context, key: `${context.key}:frag:${fragIndex}` };
                if (isStructuredEnvelopeObject(parsedValue)) {
                    if (handleStructuredEnvelope(fragContext, parsedValue, formattedEntries, state)) {
                        added = true;
                    }
                } else {
                    const contentSnapshot = extractContentSnapshotFromPayload(parsedValue);
                    if (contentSnapshot !== null) {
                        formattedEntries.push(makeFormattedEntry({
                            key: fragContext.key,
                            prefix: fragContext.prefix,
                            payload: contentSnapshot,
                            tone: 'plain',
                            format: 'pre',
                        }));
                        added = true;
                    } else {
                        const envelopeSummary = formatStructuredEnvelopeSummary(parsedValue);
                        if (envelopeSummary !== null) {
                            formattedEntries.push(makeFormattedEntry({
                                key: fragContext.key,
                                prefix: fragContext.prefix,
                                payload: envelopeSummary,
                                tone: 'structured',
                                format: 'pre',
                            }));
                            added = true;
                        }
                    }
                }
            });
            if (added || parsedValues.some((p) => isStructuredEnvelopeObject(p))) {
                return;
            }
        }

        const parsedPayload = parseJson(normalizedPayload);
        if (isRecord(parsedPayload)) {
            const handled = handleStructuredEnvelope(context, parsedPayload, formattedEntries, state);
            if (handled) {
                return;
            }
        }

        if (handleStructuredEnvelopeFragments(context, normalizedPayload, formattedEntries, state)) {
            return;
        }

        const formatted = formatAgentRunEventEntry(entry);
        if (String(formatted?.payload ?? '').trim() !== '') {
            formattedEntries.push(formatted);
        }
    });

    state.streamTextBuffers.forEach((_, streamBufferKey) => {
        flushTextBuffer(formattedEntries, state.streamTextBuffers, streamBufferKey, {
            partial: true,
            state,
        });
    });

    const nonEmptyEntries = formattedEntries.filter((entry) => String(entry?.payload ?? '').trim() !== '');

    return dedupeFormattedEntries(nonEmptyEntries);
};

const formatTimelineTimestamp = (value) => {
    const text = String(value ?? '').trim();
    if (text === '') {
        return '';
    }

    const asDate = new Date(text);
    if (!Number.isFinite(asDate.getTime())) {
        return '';
    }

    return asDate.toLocaleTimeString();
};

const extractMcpConnectionIssue = (value) => {
    const text = String(value ?? '');
    if (text === '') {
        return null;
    }

    const match = text.match(MCP_CONNECTION_REFUSED_PATTERN);
    if (!match) {
        return null;
    }

    const endpoint = String(match[1] ?? '').trim() || 'http://localhost:3333/mcp';

    return {
        key: 'mcp_server_unavailable',
        code: 'MCP_SERVER_UNAVAILABLE',
        title: 'MCP server unavailable',
        detail: `Could not connect to ${endpoint} (connection refused).`,
        suggestedAction: 'Start/restart the MCP server on port 3333 or update MCP endpoint config.',
        endpoint,
    };
};

const extractCommandExecutionFromEnvelope = (payloadObject) => {
    if (!isRecord(payloadObject)) {
        return null;
    }

    const item = isRecord(payloadObject.item)
        ? payloadObject.item
        : (isRecord(payloadObject.event?.item) ? payloadObject.event.item : null);

    if (!item || String(item.type ?? '').trim() !== 'command_execution') {
        return null;
    }

    const command = String(item.command ?? '').trim();
    const status = String(item.status ?? '').trim().toLowerCase() || 'running';
    const exitCode = Number(item.exit_code ?? NaN);
    const durationMs = Number(item.duration_ms ?? NaN);
    const output = String(item.aggregated_output ?? item.output ?? '').trim();

    return {
        command,
        status,
        exitCode: Number.isFinite(exitCode) ? exitCode : null,
        durationMs: Number.isFinite(durationMs) ? durationMs : null,
        output,
    };
};

const extractEnvelopeText = (payloadObject) => {
    if (!isRecord(payloadObject)) {
        return '';
    }

    const content = payloadObject.message ?? payloadObject.text ?? payloadObject.content;
    if (typeof content === 'string' && content.trim() !== '') {
        return content.trim();
    }
    if (Array.isArray(content)) {
        return '';
    }

    if (isRecord(payloadObject.item)) {
        const fromItem = payloadObject.item.message ?? payloadObject.item.text ?? payloadObject.item.content;
        if (typeof fromItem === 'string' && fromItem.trim() !== '') {
            return fromItem.trim();
        }
    }

    if (isRecord(payloadObject.event) && isRecord(payloadObject.event.delta)) {
        const deltaText = String(payloadObject.event.delta.text ?? '').trim();
        if (deltaText !== '') {
            return deltaText;
        }
    }

    return '';
};

const extractContentSnapshotFromPayload = (payload) => {
    if (payload === null || payload === undefined) {
        return null;
    }

    if (Array.isArray(payload)) {
        const lines = [];
        for (const item of payload) {
            if (!item || typeof item !== 'object') continue;
            const content = String(item.content ?? item.text ?? item.title ?? '').trim();
            const status = String(item.status ?? '').trim().toLowerCase();
            const activeForm = String(item.activeForm ?? item.active_form ?? '').trim();
            if (content !== '') {
                const statusLabel = status && status !== 'pending' ? ` [${status}]` : '';
                lines.push(`• ${content}${statusLabel}`);
            } else if (activeForm !== '') {
                lines.push(`• ${activeForm}${status ? ` [${status}]` : ''}`);
            }
        }
        return lines.length > 0 ? lines.join('\n') : null;
    }

    if (typeof payload === 'object') {
        const content = payload.content ?? payload.text ?? payload.message;
        if (Array.isArray(content)) {
            return extractContentSnapshotFromPayload(content);
        }
        if (typeof content === 'string' && content.trim() !== '') {
            return content.trim();
        }
        const todos = payload.todos ?? payload.items ?? payload.tasks;
        if (Array.isArray(todos)) {
            return extractContentSnapshotFromPayload(todos);
        }
        const event = payload.event;
        if (event && typeof event === 'object') {
            const delta = event.delta;
            if (delta && typeof delta === 'object' && delta.partial_json) {
                return null;
            }
        }
    }

    return null;
};

const NOISE_JSON_TYPES = new Set([
    'message_start', 'message_delta', 'content_block_start', 'content_block_delta', 'content_block_stop',
    'message_stop', 'input_json_delta', 'signature_delta', 'ping', 'pong',
]);

const NOISE_PAYLOAD_MARKERS = /"type"\s*:\s*"(?:stream_event|input_json_delta|content_block_delta|signature_delta)"/;

const inferKindFromSummaryText = (text) => {
    const t = String(text ?? '').trim();
    if (t.startsWith('Tool call:')) return 'tool_call';
    if (t.startsWith('Todo list updated')) return 'tool_result';
    return 'structured';
};

const formatStructuredEnvelopeSummary = (obj) => {
    if (!isRecord(obj)) {
        return null;
    }

    const type = String(obj.type ?? '').trim();
    if (type === 'stream_event') {
        const event = isRecord(obj.event) ? obj.event : null;
        const eventType = event ? String(event.type ?? '').trim() : '';
        if (NOISE_JSON_TYPES.has(eventType)) {
            return null;
        }
        const delta = isRecord(event?.delta) ? event.delta : null;
        const deltaType = delta ? String(delta.type ?? '').trim() : '';
        if (deltaType === 'input_json_delta' || deltaType === 'signature_delta') {
            return null;
        }
        if (eventType === 'content_block_start') {
            const block = event.content_block;
            const blockType = String(block?.type ?? '').trim();
            if (blockType === 'tool_use') {
                const name = String(block?.name ?? '').trim();
                return name ? `Tool call: ${name}` : null;
            }
        }
        if (eventType === 'message_delta' && isRecord(event.usage)) {
            const out = Number(event.usage.output_tokens ?? NaN);
            return Number.isFinite(out) && out > 0 ? `Output: ${out} tokens` : null;
        }
        return null;
    }

    if (type === 'assistant') {
        const message = isRecord(obj.message) ? obj.message : null;
        const modelName = String(message?.model ?? obj.model ?? '').trim();
        const blocks = Array.isArray(message?.content) ? message.content : [];
        const usage = isRecord(message?.usage) ? message.usage : obj.usage;
        const inTokens = Number(usage?.input_tokens ?? NaN);
        const outTokens = Number(usage?.output_tokens ?? NaN);
        const tokenStr = Number.isFinite(outTokens) && outTokens > 0 ? ` (${outTokens} output tokens)` : '';
        const isSynthetic = modelName === '<synthetic>' || (Number.isFinite(inTokens) && inTokens === 0 && Number.isFinite(outTokens) && outTokens === 0);

        for (const block of blocks) {
            if (!isRecord(block)) continue;
            const blockType = String(block.type ?? '').trim();
            if (blockType === 'tool_use') {
                const name = String(block.name ?? '').trim();
                return name ? `Tool call: ${name}${tokenStr}` : null;
            }
            if (blockType === 'text') {
                const text = String(block.text ?? '').trim();
                if (text.length > 0 && text.length <= 200) return text;
                if (text.length > 200) return `${text.slice(0, 200).trimEnd()}…`;
            }
            if (blockType === 'thinking') {
                const thinking = String(block.thinking ?? '').trim();
                if (thinking.length > 0) return `Thinking…${tokenStr}`;
            }
        }
        // Suppress synthetic messages with no meaningful content
        if (isSynthetic) return null;
        return tokenStr ? `Assistant response${tokenStr}` : null;
    }

    if (type === 'user') {
        const toolResult = obj.tool_use_result;
        if (isRecord(toolResult)) {
            const msgs = summarizeToolUseResult(toolResult);
            return msgs.length > 0 ? msgs[0] : null;
        }
        return null;
    }

    if (type === 'result') {
        const result = isRecord(obj.result) ? obj.result : null;
        if (!result) return null;
        const status = String(result.status ?? '').trim();
        const duration = Number(result.duration_ms ?? NaN);
        const parts = [];
        if (status) parts.push(status);
        if (Number.isFinite(duration)) parts.push(`${duration}ms`);
        return parts.length > 0 ? `Result: ${parts.join(', ')}` : null;
    }

    if (type === 'rate_limit_event') {
        const info = isRecord(obj.rate_limit_info) ? obj.rate_limit_info : {};
        const status = String(info.status ?? '').trim();
        const limitType = String(info.rateLimitType ?? '').trim().replace(/_/g, ' ');
        const resetsAt = Number(info.resetsAt ?? NaN);
        const overageStatus = String(info.overageStatus ?? '').trim();
        const parts = ['Rate limit'];
        if (status) parts.push(status);
        if (limitType) parts.push(`(${limitType})`);
        if (Number.isFinite(resetsAt) && resetsAt > 0) {
            const resetDate = new Date(resetsAt * 1000);
            parts.push(`- resets ${resetDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
        }
        if (overageStatus && overageStatus !== status) parts.push(`[overage: ${overageStatus}]`);
        return parts.join(' ');
    }

    if (type === 'error' || type === 'turn.failed') {
        const errorObj = isRecord(obj.error) ? obj.error : null;
        const msg = String(errorObj?.message ?? obj.message ?? obj.text ?? '').trim();
        const code = String(errorObj?.code ?? obj.code ?? '').trim();
        const label = type === 'error' ? 'Error' : 'Turn failed';
        if (msg) return code ? `${label}: ${msg} (${code})` : `${label}: ${msg}`;
        if (code) return `${label}: ${code}`;
        return label;
    }

    return null;
};

const safeDisplayText = (value) => {
    if (value === null || value === undefined) return '';
    if (typeof value === 'string') return value;
    if (typeof value === 'object') {
        const extracted = extractContentSnapshotFromPayload(value) ?? formatStructuredEnvelopeSummary(value);
        if (extracted) return extracted;
        return '';
    }
    return String(value);
};

const summarizeUnknownJsonPayload = (payloadObject) => {
    if (!isRecord(payloadObject)) {
        return null;
    }

    const type = String(payloadObject.type ?? '').trim();
    if (NOISE_JSON_TYPES.has(type)) {
        return null;
    }

    const event = isRecord(payloadObject.event) ? payloadObject.event : null;
    const eventType = event ? String(event.type ?? '').trim() : '';
    if (NOISE_JSON_TYPES.has(eventType)) {
        return null;
    }

    const msg = String(payloadObject.message ?? payloadObject.text ?? payloadObject.content ?? '').trim();
    if (msg !== '' && msg.length <= 200) {
        return msg;
    }

    const item = isRecord(payloadObject.item) ? payloadObject.item : null;
    const itemType = item ? String(item.type ?? '').trim() : '';
    const itemText = item ? String(item.text ?? item.message ?? '').trim() : '';
    if (itemText !== '' && itemText.length <= 200) {
        return itemText;
    }

    if (type === 'message_start' || type === 'message_delta') {
        return null;
    }

    if (type !== '') {
        const human = type.replace(/_/g, ' ');
        if (eventType === 'text_delta' || (event?.delta && String(event.delta?.type ?? '').trim() === 'text_delta')) {
            return null;
        }
        if (itemType === 'command_execution') {
            return null;
        }
        return human.charAt(0).toUpperCase() + human.slice(1);
    }

    if (payloadObject.status && payloadObject.duration_ms != null) {
        return `Completed (${payloadObject.status}, ${payloadObject.duration_ms}ms)`;
    }

    return null;
};

const summarizeCodexMachineEvent = (payloadObject) => {
    if (!isRecord(payloadObject)) {
        return '';
    }

    const type = String(payloadObject.type ?? '').trim();
    if (type === '') {
        return '';
    }

    if (type === 'thread.started') {
        const threadId = String(payloadObject.thread_id ?? '').trim();
        return threadId !== '' ? `Thread started (${threadId})` : 'Thread started';
    }

    if (type === 'turn.started') {
        return 'Turn started';
    }

    if (type === 'turn.completed') {
        const usage = isRecord(payloadObject.usage) ? payloadObject.usage : null;
        if (!usage) {
            return 'Turn completed';
        }

        const inputTokens = Number(usage.input_tokens ?? NaN);
        const outputTokens = Number(usage.output_tokens ?? NaN);
        const cachedInputTokens = Number(usage.cached_input_tokens ?? NaN);
        const summary = [];

        if (Number.isFinite(inputTokens) && inputTokens >= 0) {
            summary.push(`in ${inputTokens.toLocaleString()}`);
        }
        if (Number.isFinite(outputTokens) && outputTokens >= 0) {
            summary.push(`out ${outputTokens.toLocaleString()}`);
        }
        if (Number.isFinite(cachedInputTokens) && cachedInputTokens > 0) {
            summary.push(`cached ${cachedInputTokens.toLocaleString()}`);
        }

        return summary.length > 0 ? `Turn completed (${summary.join(', ')})` : 'Turn completed';
    }

    if (type === 'item.started' || type === 'item.completed') {
        const item = isRecord(payloadObject.item) ? payloadObject.item : null;
        if (!item) {
            return type === 'item.started' ? 'Item started' : 'Item completed';
        }

        const itemType = String(item.type ?? '').trim();
        if (itemType === 'command_execution') {
            return '';
        }

        if (itemType === 'file_change' && Array.isArray(item.changes)) {
            const count = item.changes.length;
            return count > 0
                ? `File changes ${type === 'item.started' ? 'started' : 'completed'} (${count} file${count === 1 ? '' : 's'})`
                : `File changes ${type === 'item.started' ? 'started' : 'completed'}`;
        }

        const text = String(item.text ?? item.message ?? '').trim();
        if (text !== '') {
            return text;
        }

        if (itemType !== '') {
            return `${itemType.replace(/_/g, ' ')} ${type === 'item.started' ? 'started' : 'completed'}`;
        }

        return type === 'item.started' ? 'Item started' : 'Item completed';
    }

    return '';
};

const collapseConsecutiveTimelineEntries = (entries) => {
    const collapsed = [];

    entries.forEach((entry) => {
        const previous = collapsed[collapsed.length - 1];
        if (!previous) {
            collapsed.push({ ...entry, repeatCount: 1 });
            return;
        }

        const sameEntry = previous.kind === entry.kind
            && previous.eventType === entry.eventType
            && String(previous.displayFormat ?? '') === String(entry.displayFormat ?? '')
            && String(previous.text ?? '') === String(entry.text ?? '')
            && String(previous.command?.command ?? '') === String(entry.command?.command ?? '');

        if (!sameEntry) {
            collapsed.push({ ...entry, repeatCount: 1 });
            return;
        }

        previous.repeatCount = Number(previous.repeatCount ?? 1) + 1;
        previous.sequence = entry.sequence;
        previous.timestamp = entry.timestamp;
        previous.timestampLabel = entry.timestampLabel;
        if (entry.command?.output) {
            previous.command = {
                ...previous.command,
                ...entry.command,
            };
        }
    });

    return collapsed;
};

const pushOrUpdateIssue = (issuesByKey, issue, sequence, timestamp) => {
    if (!issue || !issue.key) {
        return;
    }

    const existing = issuesByKey.get(issue.key);
    if (!existing) {
        issuesByKey.set(issue.key, {
            ...issue,
            count: 1,
            latestSequence: Number(sequence ?? 0),
            latestTimestamp: timestamp ?? null,
            logDetections: 1,
            countFromMetadata: 0,
        });
        return;
    }

    const nextLogDetections = Number(existing.logDetections ?? 0) + 1;
    const metadataCount = Number(existing.countFromMetadata ?? 0);

    existing.logDetections = nextLogDetections;
    existing.count = Math.max(nextLogDetections, metadataCount, Number(existing.count ?? 0));
    existing.latestSequence = Number(sequence ?? existing.latestSequence ?? 0);
    existing.latestTimestamp = timestamp ?? existing.latestTimestamp ?? null;
    if (issue.endpoint) {
        existing.endpoint = issue.endpoint;
        existing.detail = issue.detail;
    }
};

export const buildAgentRunEventPresentation = (entries, runMetadata = {}) => {
    if (!Array.isArray(entries)) {
        return {
            timelineEntries: [],
            heartbeatEntries: [],
            heartbeatSummary: null,
            issues: [],
        };
    }

    const stitchedEntries = stitchChunkedOutputEntries(entries);
    const timeline = [];
    const heartbeatEntries = [];
    const issuesByKey = new Map();

    const metadataIssues = Array.isArray(runMetadata?.issues) ? runMetadata.issues : [];
    metadataIssues.forEach((issue) => {
        const key = String(issue?.key ?? issue?.code ?? '').trim();
        if (key === '') {
            return;
        }

        issuesByKey.set(key, {
            key,
            code: String(issue?.code ?? key).trim(),
            title: String(issue?.title ?? 'Issue detected').trim(),
            detail: String(issue?.detail ?? '').trim(),
            suggestedAction: String(issue?.suggested_action ?? '').trim(),
            endpoint: String(issue?.endpoint ?? '').trim() || null,
            count: Math.max(1, Number(issue?.count ?? 1)),
            latestSequence: 0,
            latestTimestamp: String(issue?.last_detected_at ?? '').trim() || null,
            logDetections: 0,
            countFromMetadata: Math.max(1, Number(issue?.count ?? 1)),
        });
    });

    stitchedEntries.forEach((entry, index) => {
        const context = buildEntryContext(entry);
        const timestamp = String(entry?.event_ts ?? entry?.created_at ?? '').trim() || null;
        const timestampLabel = formatTimelineTimestamp(timestamp);
        const normalizedPayload = normalizeOutputPayload(context.eventType, context.payloadRaw);
        const issueFromPayload = extractMcpConnectionIssue(normalizedPayload);
        if (issueFromPayload) {
            pushOrUpdateIssue(issuesByKey, issueFromPayload, context.sequence, timestamp);
        }

        if (context.eventType === 'lifecycle') {
            const lifecyclePayload = parseJson(context.payloadRaw);
            const lifecycleType = String(lifecyclePayload?.type ?? '').trim().toLowerCase();
            const lifecycleSummary = formatLifecycleSummary(lifecyclePayload, context.fallbackTimestamp) ?? String(context.payloadRaw ?? '').trim();

            if (lifecycleSummary === '') {
                return;
            }

            const lifecycleEntry = {
                key: `${context.key}:lifecycle:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: 'lifecycle',
                displayFormat: 'text',
                text: lifecycleSummary,
                timestamp,
                timestampLabel,
            };

            if (lifecycleType === 'heartbeat') {
                heartbeatEntries.push(lifecycleEntry);
            } else {
                timeline.push(lifecycleEntry);
            }

            return;
        }

        const parsedPayload = parseJson(normalizedPayload);
        const contentSnapshot = extractContentSnapshotFromPayload(parsedPayload);
        if (contentSnapshot !== null) {
            timeline.push({
                key: `${context.key}:content:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: 'stdout',
                displayFormat: 'text',
                text: contentSnapshot,
                timestamp,
                timestampLabel,
            });
            return;
        }

        const envelopeSummary = formatStructuredEnvelopeSummary(parsedPayload);
        if (envelopeSummary !== null) {
            timeline.push({
                key: `${context.key}:envelope-summary:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: inferKindFromSummaryText(envelopeSummary),
                displayFormat: 'text',
                text: envelopeSummary,
                timestamp,
                timestampLabel,
            });
            return;
        }

        const { parsedValues } = extractJsonObjects(normalizedPayload);
        if (parsedValues.length > 1) {
            const summaries = parsedValues
                .map((p) => formatStructuredEnvelopeSummary(p) ?? extractContentSnapshotFromPayload(p))
                .filter((s) => s !== null && s !== '');
            if (summaries.length > 0) {
                const joined = summaries.join('\n');
                timeline.push({
                    key: `${context.key}:multi:${index}`,
                    sequence: context.sequence,
                    eventType: context.eventType,
                    kind: inferKindFromSummaryText(summaries[0]),
                    displayFormat: 'text',
                    text: joined,
                    timestamp,
                    timestampLabel,
                });
            }
            return;
        }

        const commandExecution = extractCommandExecutionFromEnvelope(parsedPayload);
        if (commandExecution) {
            const issueFromCommandOutput = extractMcpConnectionIssue(commandExecution.output);
            if (issueFromCommandOutput) {
                pushOrUpdateIssue(issuesByKey, issueFromCommandOutput, context.sequence, timestamp);
            }

            timeline.push({
                key: `${context.key}:command:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: 'command',
                displayFormat: 'text',
                command: commandExecution,
                text: commandExecution.command !== '' ? commandExecution.command : 'Executed command',
                timestamp,
                timestampLabel,
            });

            return;
        }

        const envelopeText = extractEnvelopeText(parsedPayload);
        if (envelopeText !== '') {
            const markdown = looksLikeMarkdown(envelopeText);
            timeline.push({
                key: `${context.key}:envelope:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: context.eventType === 'stderr' ? 'stderr' : 'stdout',
                displayFormat: markdown ? 'markdown' : 'text',
                text: envelopeText,
                timestamp,
                timestampLabel,
            });

            return;
        }

        const codexMachineSummary = summarizeCodexMachineEvent(parsedPayload);
        if (codexMachineSummary !== '') {
            timeline.push({
                key: `${context.key}:machine:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: 'structured',
                displayFormat: 'text',
                text: codexMachineSummary,
                timestamp,
                timestampLabel,
            });

            return;
        }

        if (parsedPayload !== null) {
            const summary = summarizeUnknownJsonPayload(parsedPayload);
            if (summary !== null) {
                timeline.push({
                    key: `${context.key}:json:${index}`,
                    sequence: context.sequence,
                    eventType: context.eventType,
                    kind: context.eventType === 'stderr' ? 'stderr' : 'structured',
                    displayFormat: 'text',
                    text: summary,
                    timestamp,
                    timestampLabel,
                });
            }
            return;
        }

        const readExcerptSummary = summarizeReadExcerptPayload(normalizedPayload, context.eventType);
        if (readExcerptSummary !== null) {
            timeline.push({
                key: `${context.key}:excerpt:${index}`,
                sequence: context.sequence,
                eventType: context.eventType,
                kind: 'structured',
                displayFormat: 'text',
                text: readExcerptSummary,
                timestamp,
                timestampLabel,
            });

            return;
        }

        const sequentialJson = parseSequentialJsonPayload(normalizedPayload);
        if (sequentialJson !== null) {
            const { parsedValues } = extractJsonObjects(normalizedPayload);
            const summaries = parsedValues
                .map((p) => formatStructuredEnvelopeSummary(p) ?? extractContentSnapshotFromPayload(p) ?? summarizeUnknownJsonPayload(p))
                .filter((s) => s !== null);
            if (summaries.length > 0) {
                const text = summaries.length === 1
                    ? summaries[0]
                    : `${summaries.length} events: ${summaries.slice(0, 3).join('; ')}${summaries.length > 3 ? '…' : ''}`;
                timeline.push({
                    key: `${context.key}:json-sequence:${index}`,
                    sequence: context.sequence,
                    eventType: context.eventType,
                    kind: context.eventType === 'stderr' ? 'stderr' : inferKindFromSummaryText(summaries[0]),
                    displayFormat: 'text',
                    text,
                    timestamp,
                    timestampLabel,
                });
            }
            return;
        }

        const text = String(stripLineNumberPrefixes(normalizedPayload) ?? '').trim();
        if (text === '') {
            return;
        }

        if (NOISE_PAYLOAD_MARKERS.test(text)) {
            return;
        }

        if (text.startsWith('{') || text.startsWith('[')) {
            const { parsedValues } = extractJsonObjects(text);
            const summaries = parsedValues
                .map((p) => formatStructuredEnvelopeSummary(p) ?? extractContentSnapshotFromPayload(p) ?? summarizeUnknownJsonPayload(p))
                .filter((s) => s !== null && s !== '');
            if (summaries.length > 0) {
                timeline.push({
                    key: `${context.key}:json-extract:${index}`,
                    sequence: context.sequence,
                    eventType: context.eventType,
                    kind: inferKindFromSummaryText(summaries[0]),
                    displayFormat: 'text',
                    text: summaries.join('\n'),
                    timestamp,
                    timestampLabel,
                });
            }
            return;
        }

        const markdown = looksLikeMarkdown(text);

        timeline.push({
            key: `${context.key}:text:${index}`,
            sequence: context.sequence,
            eventType: context.eventType,
            kind: context.eventType === 'stderr' ? 'stderr' : 'stdout',
            displayFormat: markdown ? 'markdown' : 'text',
            text,
            timestamp,
            timestampLabel,
        });
    });

    const collapsedTimeline = collapseConsecutiveTimelineEntries(
        timeline.sort((a, b) => Number(a.sequence ?? 0) - Number(b.sequence ?? 0))
    );
    const collapsedHeartbeat = collapseConsecutiveTimelineEntries(
        heartbeatEntries.sort((a, b) => Number(a.sequence ?? 0) - Number(b.sequence ?? 0))
    );

    const issues = Array.from(issuesByKey.values())
        .filter((issue) => String(issue.title ?? '').trim() !== '' && String(issue.detail ?? '').trim() !== '')
        .sort((a, b) => Number(b.latestSequence ?? 0) - Number(a.latestSequence ?? 0))
        .map((issue) => ({
            key: issue.key,
            code: issue.code,
            title: issue.title,
            detail: issue.detail,
            suggestedAction: issue.suggestedAction,
            endpoint: issue.endpoint,
            count: Math.max(1, Number(issue.count ?? 1)),
            latestSequence: Number(issue.latestSequence ?? 0),
            latestTimestamp: issue.latestTimestamp ?? null,
        }));

    return {
        timelineEntries: collapsedTimeline,
        heartbeatEntries: collapsedHeartbeat,
        heartbeatSummary: collapsedHeartbeat.length > 0
            ? {
                count: collapsedHeartbeat.reduce((carry, entry) => carry + Number(entry.repeatCount ?? 1), 0),
                latestTimestamp: collapsedHeartbeat[collapsedHeartbeat.length - 1]?.timestamp ?? null,
                latestTimestampLabel: collapsedHeartbeat[collapsedHeartbeat.length - 1]?.timestampLabel ?? '',
            }
            : null,
        issues,
    };
};
